import pytest

from solution import how_many_times


class TestHowManyTimes:
    def test_empty_string(self):
        assert how_many_times('', 'a') == 0

    def test_empty_string_and_empty_substring(self):
        # empty substring matches at every index, including the single
        # position of the empty string (range(len(''))) -> no positions
        assert how_many_times('', '') == 0

    def test_no_occurrences(self):
        assert how_many_times('abc', 'z') == 0

    def test_single_occurrence(self):
        assert how_many_times('abc', 'b') == 1

    def test_multiple_non_overlapping_occurrences(self):
        assert how_many_times('abcabcabc', 'abc') == 3

    def test_simple_repeated_char(self):
        assert how_many_times('aaa', 'a') == 3

    def test_overlapping_occurrences(self):
        assert how_many_times('aaaa', 'aa') == 3

    def test_overlapping_occurrences_longer(self):
        assert how_many_times('aaaaa', 'aa') == 4

    def test_substring_longer_than_string(self):
        assert how_many_times('a', 'aa') == 0

    def test_substring_equal_to_string(self):
        assert how_many_times('abc', 'abc') == 1

    def test_substring_not_present_partial_match(self):
        assert how_many_times('abcdef', 'abcdefg') == 0

    def test_single_char_string_match(self):
        assert how_many_times('a', 'a') == 1

    def test_single_char_string_no_match(self):
        assert how_many_times('a', 'b') == 0

    def test_empty_substring_on_nonempty_string(self):
        # empty substring "found" at every starting index in range(len(string))
        assert how_many_times('abc', '') == 3

    def test_overlapping_repeated_pattern(self):
        assert how_many_times('banana', 'ana') == 2

    def test_case_sensitivity(self):
        assert how_many_times('AAA', 'a') == 0

    def test_whitespace_substring(self):
        assert how_many_times('a b c d', ' ') == 3

    def test_multi_char_no_overlap_possible(self):
        assert how_many_times('aabbaabb', 'bb') == 2

    def test_special_characters(self):
        assert how_many_times('a.b.c.', '.') == 3

    def test_repeated_full_overlap_single_char_long_string(self):
        assert how_many_times('a' * 10, 'a') == 10

    def test_return_type_is_int(self):
        result = how_many_times('aaa', 'a')
        assert isinstance(result, int)

    @pytest.mark.parametrize(
        "string, substring, expected",
        [
            ('', 'a', 0),
            ('aaa', 'a', 3),
            ('aaaa', 'aa', 3),
            ('xyz', 'xyz', 1),
            ('xyzxyz', 'xyz', 2),
        ],
    )
    def test_parametrized_cases(self, string, substring, expected):
        assert how_many_times(string, substring) == expected
