import pytest

from solution import filter_integers


class TestFilterIntegers:
    def test_docstring_example_mixed_types(self):
        assert filter_integers(['a', 3.14, 5]) == [5]

    def test_docstring_example_multiple_ints(self):
        assert filter_integers([1, 2, 3, 'abc', {}, []]) == [1, 2, 3]

    def test_empty_list(self):
        assert filter_integers([]) == []

    def test_all_integers(self):
        assert filter_integers([1, 2, 3, 4]) == [1, 2, 3, 4]

    def test_no_integers(self):
        assert filter_integers(['a', 'b', 3.14, None, {}, [], (1, 2)]) == []

    def test_negative_and_zero_integers(self):
        assert filter_integers([-5, 0, 7, -1]) == [-5, 0, 7, -1]

    def test_excludes_floats(self):
        assert filter_integers([1.0, 2.5, 3.0]) == []

    def test_excludes_booleans(self):
        # bool is a subclass of int, but type(x) == int excludes bool explicitly
        assert filter_integers([True, False, 1, 0]) == [1, 0]

    def test_excludes_strings_that_look_like_numbers(self):
        assert filter_integers(['1', '2', '3']) == []

    def test_excludes_none(self):
        assert filter_integers([None, 1, None, 2]) == [1, 2]

    def test_excludes_complex_numbers(self):
        assert filter_integers([1 + 2j, 3, 4 - 1j]) == [3]

    def test_excludes_containers(self):
        assert filter_integers([[1, 2], {'a': 1}, (1,), {1, 2}, 5]) == [5]

    def test_preserves_order(self):
        assert filter_integers([3, 'a', 1, 'b', 2]) == [3, 1, 2]

    def test_large_integers(self):
        big = 10**20
        assert filter_integers([big, 'x', -big]) == [big, -big]

    def test_excludes_int_subclass_instances(self):
        class MyInt(int):
            pass

        # type(x) == int excludes subclasses, unlike isinstance
        assert filter_integers([MyInt(5), 3]) == [3]

    def test_returns_new_list_not_same_object(self):
        original = [1, 2, 3]
        result = filter_integers(original)
        assert result == original
        assert result is not original

    def test_return_type_is_list(self):
        result = filter_integers([1, 'a', 2])
        assert isinstance(result, list)

    def test_duplicates_preserved(self):
        assert filter_integers([1, 1, 2, 2, 'a']) == [1, 1, 2, 2]

    def test_mixed_with_functions_and_classes(self):
        def f():
            pass

        class C:
            pass

        assert filter_integers([f, C, int, 9]) == [9]
