import pytest

from solution import odd_count


def build_expected(counts):
    """Helper to build expected strings for a list of odd-digit counts."""
    template = "the number of odd elements in the string i of the input."
    return [template.replace("i", str(c)) for c in counts]


class TestOddCountBasic:
    def test_docstring_example_single(self):
        assert odd_count(['1234567']) == [
            "the number of odd elements 4n the str4ng 4 of the 4nput."
        ]

    def test_docstring_example_multiple(self):
        assert odd_count(['3', "11111111"]) == [
            "the number of odd elements 1n the str1ng 1 of the 1nput.",
            "the number of odd elements 8n the str8ng 8 of the 8nput.",
        ]

    def test_empty_list_returns_empty_list(self):
        assert odd_count([]) == []

    def test_single_odd_digit(self):
        assert odd_count(['1']) == [
            "the number of odd elements 1n the str1ng 1 of the 1nput."
        ]

    def test_single_even_digit(self):
        assert odd_count(['2']) == [
            "the number of odd elements 0n the str0ng 0 of the 0nput."
        ]

    def test_all_even_digits(self):
        assert odd_count(['2468']) == [
            "the number of odd elements 0n the str0ng 0 of the 0nput."
        ]

    def test_all_odd_digits(self):
        assert odd_count(['13579']) == [
            "the number of odd elements 5n the str5ng 5 of the 5nput."
        ]

    def test_mixed_digits(self):
        # digits: 1,0,2,3,4,5,6,7,8,9 -> odd: 1,3,5,7,9 = 5
        assert odd_count(['0123456789']) == [
            "the number of odd elements 5n the str5ng 5 of the 5nput."
        ]

    def test_zero_string(self):
        assert odd_count(['0']) == [
            "the number of odd elements 0n the str0ng 0 of the 0nput."
        ]

    def test_multiple_strings_preserves_order(self):
        result = odd_count(['0', '1', '22', '333'])
        expected = build_expected([0, 1, 0, 3])
        assert result == expected

    def test_return_type_is_list(self):
        result = odd_count(['123'])
        assert isinstance(result, list)

    def test_output_length_matches_input_length(self):
        inputs = ['1', '22', '333', '4444', '55555']
        result = odd_count(inputs)
        assert len(result) == len(inputs)

    def test_each_element_is_string(self):
        result = odd_count(['12', '34', '56'])
        assert all(isinstance(item, str) for item in result)

    def test_double_digit_odd_count(self):
        # 20 characters all odd digits -> odd_cnt = 20, "i" replaced with "20"
        s = "1" * 20
        result = odd_count([s])
        assert result == [
            "the number of odd elements 20n the str20ng 20 of the 20nput."
        ]

    def test_long_string_of_zeros(self):
        s = "0" * 50
        result = odd_count([s])
        assert result == [
            "the number of odd elements 0n the str0ng 0 of the 0nput."
        ]

    def test_repeated_identical_strings(self):
        result = odd_count(['13', '13', '13'])
        expected = build_expected([2, 2, 2])
        assert result == expected

    @pytest.mark.parametrize(
        "s, expected_count",
        [
            ("1", 1),
            ("2", 0),
            ("13", 2),
            ("24", 0),
            ("123456789", 5),
            ("111111111", 9),
            ("000000000", 0),
            ("97531", 5),
            ("86420", 0),
        ],
    )
    def test_parametrized_counts(self, s, expected_count):
        result = odd_count([s])
        assert result == build_expected([expected_count])

    def test_does_not_mutate_input_list(self):
        original = ['123', '456']
        input_copy = list(original)
        odd_count(original)
        assert original == input_copy

    def test_large_batch_consistency(self):
        inputs = [str(i) for i in range(20)]
        result = odd_count(inputs)
        expected = [
            build_expected([sum(1 for ch in s if int(ch) % 2 == 1)])[0]
            for s in inputs
        ]
        assert result == expected
