import pytest

from solution import split_words


class TestWhitespaceSplitting:
    def test_simple_space(self):
        assert split_words("Hello world!") == ["Hello", "world!"]

    def test_multiple_words_space_separated(self):
        assert split_words("The quick brown fox") == ["The", "quick", "brown", "fox"]

    def test_tab_separated(self):
        assert split_words("Hello\tworld!") == ["Hello", "world!"]

    def test_newline_separated(self):
        assert split_words("Hello\nworld!") == ["Hello", "world!"]

    def test_carriage_return_separated(self):
        assert split_words("Hello\rworld!") == ["Hello", "world!"]

    def test_multiple_consecutive_spaces_collapsed(self):
        assert split_words("Hello    world!") == ["Hello", "world!"]

    def test_leading_and_trailing_whitespace_stripped(self):
        assert split_words("  Hello world!  ") == ["Hello", "world!"]

    def test_mixed_whitespace_types(self):
        assert split_words("Hello \t\n world!") == ["Hello", "world!"]

    def test_whitespace_takes_priority_over_comma(self):
        # Contains both whitespace and commas -> should split on whitespace
        assert split_words("Hello, world!") == ["Hello,", "world!"]

    def test_only_whitespace_returns_empty_list(self):
        assert split_words("   ") == []

    def test_single_word_with_trailing_space(self):
        assert split_words("Hello ") == ["Hello"]


class TestCommaSplitting:
    def test_simple_comma(self):
        assert split_words("Hello,world!") == ["Hello", "world!"]

    def test_multiple_commas(self):
        assert split_words("a,b,c,d") == ["a", "b", "c", "d"]

    def test_comma_with_no_surrounding_spaces(self):
        assert split_words("one,two,three") == ["one", "two", "three"]

    def test_trailing_comma_produces_empty_string_element(self):
        assert split_words("Hello,world,") == ["Hello", "world", ""]

    def test_leading_comma_produces_empty_string_element(self):
        assert split_words(",Hello,world") == ["", "Hello", "world"]

    def test_only_commas(self):
        assert split_words(",,,") == ["", "", "", ""]


class TestOddLetterCounting:
    def test_example_abcdef(self):
        assert split_words("abcdef") == 3

    def test_no_lowercase_letters_returns_zero(self):
        assert split_words("12345!@#$%") == 0

    def test_empty_string_returns_zero(self):
        assert split_words("") == 0

    def test_all_even_index_letters_returns_zero(self):
        # a=0, c=2, e=4, g=6 -> all even indices
        assert split_words("aceg") == 0

    def test_all_odd_index_letters(self):
        # b=1, d=3, f=5, h=7 -> all odd indices
        assert split_words("bdfh") == 4

    def test_uppercase_letters_not_counted(self):
        # Uppercase letters should be ignored entirely
        assert split_words("BDFH") == 0

    def test_mixed_case_only_lowercase_counted(self):
        # b(odd),D(upper,ignored),f(odd),H(upper,ignored) -> only b,f count
        assert split_words("bDfH") == 2

    def test_z_is_odd_index(self):
        # z -> ord('z') - ord('a') = 25, odd -> counted
        assert split_words("z") == 1

    def test_a_is_even_index(self):
        assert split_words("a") == 0

    def test_full_alphabet_lowercase(self):
        # 13 odd-indexed letters: b,d,f,h,j,l,n,p,r,t,v,x,z
        assert split_words("abcdefghijklmnopqrstuvwxyz") == 13

    def test_repeated_odd_letters(self):
        assert split_words("bbbb") == 4

    def test_non_alpha_characters_ignored(self):
        assert split_words("b1d2f3") == 3


class TestReturnTypes:
    def test_whitespace_case_returns_list(self):
        assert isinstance(split_words("a b"), list)

    def test_comma_case_returns_list(self):
        assert isinstance(split_words("a,b"), list)

