class TestSimplifyTruthyCases:
    @pytest.mark.parametrize(
        "x, n",
        [
            ("1/5", "5/1"),          # 1*5 / 5*1 = 5/5 -> whole
            ("1/1", "1/1"),          # 1/1 -> whole
            ("3/4", "4/3"),          # (3*4)/(4*3) = 12/12 -> whole
            ("5/3", "3/5"),          # (5*3)/(3*5) = 15/15 -> whole
            ("10/1", "1/10"),        # (10*1)/(1*10) = 10/10 -> whole
            ("6/4", "4/6"),          # (6*4)/(4*6) = 24/24 -> whole
            ("1000000/3", "3/1000000"),  # large numbers, still cancels out
            ("2/1", "3/1"),          # (2*3)/(1*1) = 6/1 -> whole
            ("4/2", "1/2"),          # (4*1)/(2*2) = 4/4 -> whole
        ],
    )
    def test_returns_true(self, x, n):
        assert simplify(x, n) is True


class TestSimplifyFalsyCases:
    @pytest.mark.parametrize(
        "x, n",
        [
            ("1/6", "2/1"),      # (1*2)/(6*1) = 2/6 -> not whole
            ("7/10", "10/2"),    # (7*10)/(10*2) = 70/20 -> not whole
            ("2/3", "3/4"),      # (2*3)/(3*4) = 6/12 -> not whole
            ("1/7", "7/2"),      # (1*7)/(7*2) = 7/14 -> not whole
            ("3/8", "5/2"),      # (3*5)/(8*2) = 15/16 -> not whole
            ("1/2", "1/3"),      # (1*1)/(2*3) = 1/6 -> not whole
            ("2/9", "5/18"),     # (2*5)/(9*18) = 10/162 -> not whole
        ],
    )
    def test_returns_false(self, x, n):
        assert simplify(x, n) is False


class TestSimplifyReturnType:
    def test_return_type_is_bool_when_true(self):
        result = simplify("1/5", "5/1")
        assert isinstance(result, bool)
        assert result is True

    def test_return_type_is_bool_when_false(self):
        result = simplify("1/6", "2/1")
        assert isinstance(result, bool)
        assert result is False


class TestSimplifyArgumentOrderIndependence:
    @pytest.mark.parametrize(
        "x, n",
        [
            ("1/5", "5/1"),
            ("1/6", "2/1"),
            ("3/4", "4/3"),
            ("2/3", "3/4"),
        ],
    )
    def test_multiplication_is_commutative(self, x, n):
        # Since x * n == n * x mathematically, swapping arguments
        # should not change the result.
        assert simplify(x, n) == simplify(n, x)


