from solution import truncate_number


class TestTruncateNumber:
    def test_doctest_example(self):
        assert truncate_number(3.5) == pytest.approx(0.5)

    def test_simple_fraction(self):
        assert truncate_number(1.25) == pytest.approx(0.25)

    def test_integer_valued_float_returns_zero(self):
        assert truncate_number(5.0) == pytest.approx(0.0)

    def test_zero_returns_zero(self):
        assert truncate_number(0.0) == pytest.approx(0.0)

    def test_small_fraction_less_than_one(self):
        assert truncate_number(0.75) == pytest.approx(0.75)

    def test_large_number_with_fraction(self):
        assert truncate_number(123456.6789) == pytest.approx(0.6789)

    def test_value_close_to_next_integer(self):
        assert truncate_number(9.9999) == pytest.approx(0.9999)

    def test_value_just_above_integer(self):
        assert truncate_number(10.0001) == pytest.approx(0.0001, abs=1e-9)

    def test_repeated_call_is_stable(self):
        result_1 = truncate_number(7.42)
        result_2 = truncate_number(7.42)
        assert result_1 == pytest.approx(result_2)

    def test_result_is_always_less_than_one(self):
        for value in [1.1, 2.99, 100.5, 0.001, 999999.999999]:
            assert truncate_number(value) < 1

    def test_result_is_non_negative(self):
        for value in [1.1, 2.99, 100.5, 0.001, 999999.999999]:
            assert truncate_number(value) >= 0

    def test_return_type_is_float(self):
        assert isinstance(truncate_number(3.5), float)

    @pytest.mark.parametrize(
        "number, expected",
        [
            (3.5, 0.5),
            (1.0, 0.0),
            (2.333, 0.333),
            (100.001, 0.001),
            (0.5, 0.5),
        ],
    )
    def test_parametrized_values(self, number, expected):
        assert truncate_number(number) == pytest.approx(expected, abs=1e-6)

    def test_matches_manual_decomposition(self):
        number = 42.123456
        integer_part = int(number)
        decimal_part = truncate_number(number)
        assert math.isclose(integer_part + decimal_part, number)
