    def test_full_overlap_all_same_character(self):
        assert how_many_times('aaaaaa', 'a') == 6

    def test_case_sensitivity(self):
        assert how_many_times('AaAaAa', 'a') == 3

    def test_special_characters(self):
        assert how_many_times('a.b.c.', '.') == 3

    def test_numeric_like_strings(self):
        assert how_many_times('123123123', '123') == 3

    def test_whitespace_substring(self):
