import pytest

from solution import fibfib


# ---------------------------------------------------------------------------
# Reference (independent) implementation used to cross-check fibfib for many
# values without duplicating the iterative logic under test.
# ---------------------------------------------------------------------------
def _reference_fibfib(n: int) -> int:
    cache = {0: 0, 1: 0, 2: 1}

    def helper(k):
        if k in cache:
            return cache[k]
        val = helper(k - 1) + helper(k - 2) + helper(k - 3)
        cache[k] = val
        return val

    return helper(n)


class TestFibFibBaseCases:
    def test_fibfib_zero(self):
        assert fibfib(0) == 0

    def test_fibfib_one(self):
        assert fibfib(1) == 0

    def test_fibfib_two(self):
        assert fibfib(2) == 1


class TestFibFibDocstringExamples:
    def test_fibfib_five(self):
        assert fibfib(5) == 4

    def test_fibfib_eight(self):
        assert fibfib(8) == 24


class TestFibFibKnownValues:
    @pytest.mark.parametrize(
        "n, expected",
        [
            (0, 0),
            (1, 0),
            (2, 1),
            (3, 1),   # 0 + 0 + 1
            (4, 2),   # 0 + 1 + 1
            (5, 4),   # 1 + 1 + 2
            (6, 7),   # 1 + 2 + 4
            (7, 13),  # 2 + 4 + 7
            (8, 24),  # 4 + 7 + 13
            (9, 44),  # 7 + 13 + 24
            (10, 81), # 13 + 24 + 44
        ],
    )
    def test_known_sequence_values(self, n, expected):
        assert fibfib(n) == expected


class TestFibFibRecurrenceRelation:
    @pytest.mark.parametrize("n", range(3, 30))
    def test_recurrence_holds(self, n):
        # fibfib(n) must equal the sum of the previous three terms.
        assert fibfib(n) == fibfib(n - 1) + fibfib(n - 2) + fibfib(n - 3)

    @pytest.mark.parametrize("n", list(range(0, 40)))
    def test_matches_reference_implementation(self, n):
        assert fibfib(n) == _reference_fibfib(n)


class TestFibFibLargerInputs:
    def test_moderate_value(self):
        assert fibfib(15) == _reference_fibfib(15)

    def test_larger_value(self):
        assert fibfib(30) == _reference_fibfib(30)

    def test_return_type_is_int(self):
        result = fibfib(20)
        assert isinstance(result, int)

    def test_monotonic_non_decreasing_for_n_ge_2(self):
        # From n=2 onward, all terms are non-negative and non-decreasing.
        values = [fibfib(n) for n in range(2, 25)]
        assert all(later >= earlier for earlier, later in zip(values, values[1:]))


class TestFibFibEfficiency:
    def test_handles_reasonably_large_n_quickly(self):
        # Should complete essentially instantly if implemented iteratively;
        # this guards against accidental reintroduction of naive recursion.
        result = fibfib(500)
        assert isinstance(result, int)
        assert result > 0
