class TestCountUpper:
    def test_example_mixed_case(self):
        assert count_upper('aBCdEf') == 1

    def test_example_all_lowercase(self):
        assert count_upper('abcdefg') == 0

    def test_example_no_upper_at_even_indices(self):
        assert count_upper('dBBE') == 0

    def test_empty_string(self):
        assert count_upper('') == 0

    def test_single_char_uppercase_vowel(self):
        assert count_upper('A') == 1

    def test_single_char_uppercase_consonant(self):
        assert count_upper('B') == 0

    def test_single_char_lowercase_vowel(self):
        assert count_upper('a') == 0

    def test_all_uppercase_vowels_even_indices(self):
        # indices 0,2,4 -> A, E, I
        assert count_upper('AxExIxOxU') == 3

    def test_uppercase_vowels_only_at_odd_indices_not_counted(self):
        # A,E,I,O,U placed at odd indices should not be counted
        assert count_upper('xAxExIxOxU') == 0

    def test_all_uppercase_vowels_string(self):
        # 'AEIOU' -> indices 0,2,4 are A,I,U (all vowels)
        assert count_upper('AEIOU') == 3

    def test_lowercase_vowels_not_counted(self):
        assert count_upper('aeiou') == 0

    def test_uppercase_consonants_not_counted(self):
        assert count_upper('BCDFG') == 0

    def test_mixed_string_with_non_alpha_chars(self):
        # even indices: 'A', '1', 'E' -> 2 uppercase vowels
        assert count_upper('A1E2!3') == 2

    def test_long_string_all_even_indices_uppercase_vowels(self):
        s = 'A-E-I-O-U-'
        # indices 0,2,4,6,8 = A,E,I,O,U -> all counted
        assert count_upper(s) == 5

    def test_repeated_pattern(self):
        assert count_upper('AaAaAaAa') == 4

    def test_two_char_string_even_index_only(self):
        assert count_upper('AB') == 1

    def test_two_char_string_no_vowel(self):
        assert count_upper('BC') == 0

    @pytest.mark.parametrize(
        "s,expected",
        [
            ('A', 1),
            ('E', 1),
            ('I', 1),
            ('O', 1),
            ('U', 1),
            ('a', 0),
            ('e', 0),
            ('i', 0),
            ('o', 0),
            ('u', 0),
        ],
    )
    def test_single_vowel_characters(self, s, expected):
        assert count_upper(s) == expected

    def test_full_alphabet_uppercase(self):
        s = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
        # even indices (0-based): A,C,E,G,I,K,M,O,Q,S,U,W,Y
        # vowels among those: A, E, I, O, U -> 5
        assert count_upper(s) == 5

    def test_does_not_mutate_input(self):
        s = 'aBCdEf'
        count_upper(s)
        assert s == 'aBCdEf'
