import pytest

from solution import words_string


def test_example_one():
    assert words_string("Hi, my name is John") == ["Hi", "my", "name", "is", "John"]


def test_example_two():
    assert words_string("One, two, three, four, five, six") == [
        "One",
        "two",
        "three",
        "four",
        "five",
        "six",
    ]


def test_empty_string():
    assert words_string("") == []


def test_only_commas():
    assert words_string(",,,") == []


def test_only_spaces():
    assert words_string("     ") == []


def test_only_commas_and_spaces():
    assert words_string(" , , , ") == []


def test_single_word_no_separators():
    assert words_string("Hello") == ["Hello"]


def test_words_separated_by_spaces_only():
    assert words_string("Hello world foo bar") == ["Hello", "world", "foo", "bar"]


def test_words_separated_by_commas_only():
    assert words_string("Hello,world,foo,bar") == ["Hello", "world", "foo", "bar"]


def test_mixed_commas_and_spaces():
    assert words_string("Hello, world,foo bar,baz") == [
        "Hello",
        "world",
        "foo",
        "bar",
        "baz",
    ]


def test_multiple_consecutive_commas():
    assert words_string("a,,b,,,c") == ["a", "b", "c"]


def test_multiple_consecutive_spaces():
    assert words_string("a    b     c") == ["a", "b", "c"]


def test_leading_and_trailing_commas():
    assert words_string(",a,b,c,") == ["a", "b", "c"]


def test_leading_and_trailing_spaces():
    assert words_string("  a b c  ") == ["a", "b", "c"]


def test_leading_and_trailing_commas_and_spaces():
    assert words_string(" , a, b , c , ") == ["a", "b", "c"]


def test_comma_immediately_followed_by_space():
    assert words_string("a, b, c") == ["a", "b", "c"]


def test_tabs_and_newlines_treated_as_whitespace():
    assert words_string("a\tb\nc") == ["a", "b", "c"]


