import pytest

from solution import odd_count


def _expected(s):
    """Reference implementation used only to build expected strings in tests."""
    odd_cnt = sum(1 for ch in s if int(ch) % 2 == 1)
    template = "the number of odd elements in the string i of the input."
    return template.replace("i", str(odd_cnt))


class TestOddCountDocstringExamples:
    def test_single_string_mixed_digits(self):
        assert odd_count(['1234567']) == [
            "the number of odd elements 4n the str4ng 4 of the 4nput."
        ]

    def test_two_strings(self):
        assert odd_count(['3', "11111111"]) == [
            "the number of odd elements 1n the str1ng 1 of the 1nput.",
            "the number of odd elements 8n the str8ng 8 of the 8nput.",
        ]


class TestOddCountBasicBehavior:
    def test_empty_list_returns_empty_list(self):
        assert odd_count([]) == []

    def test_empty_string_zero_odd_digits(self):
        assert odd_count(['']) == [
            "the number of odd elements 0n the str0ng 0 of the 0nput."
        ]

    def test_all_even_digits(self):
        assert odd_count(['0246802468']) == [
            "the number of odd elements 0n the str0ng 0 of the 0nput."
        ]

    def test_all_odd_digits(self):
        s = '13579'
        assert odd_count([s]) == [_expected(s)]

    def test_single_zero(self):
        assert odd_count(['0']) == [
            "the number of odd elements 0n the str0ng 0 of the 0nput."
        ]

    def test_single_odd_digit(self):
        assert odd_count(['7']) == [
            "the number of odd elements 1n the str1ng 1 of the 1nput."
        ]

    def test_repeated_odd_digit(self):
        assert odd_count(['9999']) == [
            "the number of odd elements 4n the str4ng 4 of the 4nput."
        ]

    def test_long_string_many_digits(self):
        s = '1234567890' * 3  # 15 odd digits total
        assert odd_count([s]) == [_expected(s)]
        assert "15" in odd_count([s])[0]

    def test_output_length_matches_input_length(self):
        lst = ['1', '22', '333', '4444', '']
        result = odd_count(lst)
        assert len(result) == len(lst)

    def test_output_order_preserved(self):
        lst = ['1', '2', '3', '4']
        result = odd_count(lst)
        expected = [_expected(s) for s in lst]
        assert result == expected

    def test_returns_list_of_strings(self):
        result = odd_count(['123', '456'])
        assert isinstance(result, list)
        assert all(isinstance(item, str) for item in result)

    @pytest.mark.parametrize(
        "s",
        [
            '0',
            '1',
            '10',
            '99',
            '1029384756',
            '000000',
            '111111',
            '5',
            '24680',
            '13579',
        ],
    )
    def test_parametrized_various_strings(self, s):
        assert odd_count([s]) == [_expected(s)]

    def test_multiple_entries_independent_counts(self):
        lst = ['1234567', '3', '11111111', '0', '2468']
        result = odd_count(lst)
        assert result == [_expected(s) for s in lst]

    def test_does_not_mutate_input_list(self):
        lst = ['123', '456']
        original = list(lst)
        odd_count(lst)
        assert lst == original

    def test_template_structure_preserved_except_digits(self):
        result = odd_count(['22'])[0]
        assert result.startswith("the number of odd elements ")
        assert result.endswith(" of the 0nput.")
        assert "str0ng" in result

