import pytest

from solution import split_words


class TestSplitWordsWhitespace:
    def test_space_separated(self):
        assert split_words("Hello world!") == ["Hello", "world!"]

    def test_multiple_words_spaces(self):
        assert split_words("olleh dlrow abc") == ["olleh", "dlrow", "abc"]

    def test_tab_separated(self):
        assert split_words("Hello\tworld!") == ["Hello", "world!"]

    def test_newline_separated(self):
        assert split_words("Hello\nworld!") == ["Hello", "world!"]

    def test_carriage_return_separated(self):
        assert split_words("Hello\rworld!") == ["Hello", "world!"]

    def test_whitespace_takes_priority_over_comma(self):
        # Contains both whitespace and commas -> whitespace rule wins
        assert split_words("Hello, world, again") == ["Hello,", "world,", "again"]

    def test_leading_trailing_and_multiple_spaces(self):
        # str.split() with no args collapses runs of whitespace and strips ends
        assert split_words("  Hello   world!  ") == ["Hello", "world!"]

    def test_single_space(self):
        assert split_words(" ") == []


class TestSplitWordsComma:
    def test_comma_separated(self):
        assert split_words("Hello,world!") == ["Hello", "world!"]

    def test_multiple_commas(self):
        assert split_words("a,b,c") == ["a", "b", "c"]

    def test_comma_with_empty_fields(self):
        assert split_words("a,,b") == ["a", "", "b"]

    def test_single_comma(self):
        assert split_words(",") == ["", ""]

    def test_trailing_comma(self):
        assert split_words("abc,") == ["abc", ""]


class TestSplitWordsOddOrdCount:
    def test_example_abcdef(self):
        # a(0) even, b(1) odd, c(2) even, d(3) odd, e(4) even, f(5) odd -> 3
        assert split_words("abcdef") == 3

    def test_no_whitespace_no_comma_all_upper(self):
        # No lowercase letters at all -> count is 0
        assert split_words("ABCDEF") == 0

    def test_single_odd_letter(self):
        assert split_words("b") == 1

    def test_single_even_letter(self):
        assert split_words("a") == 0

    def test_empty_string(self):
        assert split_words("") == 0

    def test_mixed_case_and_digits(self):
        # lowercase letters: b(1,odd), d(3,odd), f(5,odd) among noise -> 3
        assert split_words("A1b2C3d4E5f") == 3

    def test_full_alphabet_lowercase(self):
