        # index 4 and 8 are multiples of 4 but not 3 -> cubed
        lst = [0, 0, 0, 0, 2, 0, 0, 0, 3]
        # i4: 2**3=8, i8: 3**3=27 (index0 is 0 so contributes 0 either way)
        assert sum_squares(lst) == 8 + 27

