        # i5: 6
        # i6 (mult3): 7**2 = 49
        # i7: 8
        # i8 (mult4): 9**3 = 729
        # i9 (mult3): 10**2 = 100
        expected = 1 + 2 + 3 + 16 + 125 + 6 + 49 + 8 + 729 + 100
        assert sum_squares(lst) == expected


class TestNegativeAndZeroValues:
