            (1, (0, 1)),
            (2, (1, 0)),
            (12345, (2, 3)),
            (-12345, (2, 3)),
            (1000000, (7, 0)),
            (999999, (0, 6)),
        ],
    )
    def test_parametrized_cases(self, num, expected):
        assert even_odd_count(num) == expected

    def test_return_type_is_tuple(self):
        result = even_odd_count(123)
        assert isinstance(result, tuple)
