import pytest

from solution import how_many_times


class TestHowManyTimes:
    def test_empty_string_and_nonempty_substring(self):
        assert how_many_times('', 'a') == 0

    def test_no_overlap_matches(self):
        assert how_many_times('aaa', 'a') == 3

    def test_overlapping_matches(self):
        assert how_many_times('aaaa', 'aa') == 3

    def test_substring_not_present(self):
        assert how_many_times('abcdef', 'xyz') == 0

    def test_substring_equals_string(self):
        assert how_many_times('hello', 'hello') == 1

    def test_substring_longer_than_string(self):
        assert how_many_times('hi', 'hello') == 0

    def test_single_character_string_and_substring_match(self):
        assert how_many_times('a', 'a') == 1

    def test_single_character_string_no_match(self):
        assert how_many_times('a', 'b') == 0

    def test_repeated_word_overlapping(self):
        assert how_many_times('abababab', 'aba') == 3

    def test_non_overlapping_word_pattern(self):
        assert how_many_times('abcabcabc', 'abc') == 3

    def test_case_sensitivity(self):
        assert how_many_times('AAA', 'a') == 0

    def test_partial_match_at_end_not_counted(self):
        assert how_many_times('aab', 'ab') == 1

    def test_multi_character_substring_no_overlap_possible(self):
        assert how_many_times('xyxyxy', 'yx') == 2

    def test_both_empty(self):
        assert how_many_times('', '') == 0

    def test_empty_substring_on_nonempty_string(self):
        # startswith('') is True at every index, so each position counts.
        assert how_many_times('abc', '') == 3

    def test_whitespace_substring(self):
        assert how_many_times('a a a', ' ') == 2

    def test_single_char_repeated_long_string(self):
        assert how_many_times('a' * 10, 'a') == 10

    def test_overlapping_long_pattern(self):
        assert how_many_times('aaaaa', 'aaa') == 3

    @pytest.mark.parametrize(
        "string, substring, expected",
        [
            ('', 'a', 0),
            ('aaa', 'a', 3),
            ('aaaa', 'aa', 3),
        ],
    )
    def test_docstring_examples(self, string, substring, expected):
        assert how_many_times(string, substring) == expected
