        assert sum_to_n(2) == 3

    def test_three(self):
        assert sum_to_n(3) == 6

    def test_negative_number_returns_zero_or_negative(self):
        # (n+1)*n // 2 for n=-1 -> (0)*(-1)//2 == 0
        assert sum_to_n(-1) == 0

    def test_negative_number_minus_two(self):
        # (n+1)*n // 2 for n=-2 -> (-1)*(-2)//2 == 1
        assert sum_to_n(-2) == 1

    def test_large_number(self):
        n = 10**6
        assert sum_to_n(n) == n * (n + 1) // 2

    def test_matches_gauss_formula_for_range(self):
        for n in range(0, 50):
            assert sum_to_n(n) == n * (n + 1) // 2

    def test_matches_naive_sum_for_range(self):
        for n in range(1, 50):
