import pytest

from solution import fibfib


# Reference sequence computed directly from the recurrence relation:
# fibfib(0) == 0, fibfib(1) == 0, fibfib(2) == 1,
# fibfib(n) == fibfib(n-1) + fibfib(n-2) + fibfib(n-3)
EXPECTED = [0, 0, 1, 1, 2, 4, 7, 13, 24, 44, 81, 149, 274, 504, 927, 1705, 3136]


class TestFibFibBaseCases:
    def test_fibfib_zero(self):
        assert fibfib(0) == 0

    def test_fibfib_one(self):
        assert fibfib(1) == 0

    def test_fibfib_two(self):
        assert fibfib(2) == 1


class TestFibFibDocstringExamples:
    def test_fibfib_1(self):
        assert fibfib(1) == 0

    def test_fibfib_5(self):
        assert fibfib(5) == 4

    def test_fibfib_8(self):
        assert fibfib(8) == 24


class TestFibFibKnownValues:
    @pytest.mark.parametrize("n, expected", list(enumerate(EXPECTED)))
    def test_known_sequence_values(self, n, expected):
        assert fibfib(n) == expected


class TestFibFibRecurrence:
    def test_recurrence_relation_holds(self):
        # For n >= 3, fibfib(n) == fibfib(n-1) + fibfib(n-2) + fibfib(n-3)
        for n in range(3, 30):
            assert fibfib(n) == fibfib(n - 1) + fibfib(n - 2) + fibfib(n - 3)


class TestFibFibLargerInputs:
    def test_fibfib_20(self):
        assert fibfib(20) == 26499

    def test_fibfib_30(self):
        assert fibfib(30) == 3736710778

    def test_large_n_runs_efficiently(self):
        # Should complete quickly (iterative, not exponential recursion)
        result = fibfib(1000)
        assert isinstance(result, int)
        assert result > 0


class TestFibFibReturnType:
    @pytest.mark.parametrize("n", [0, 1, 2, 3, 10, 50])
    def test_return_type_is_int(self, n):
        assert isinstance(fibfib(n), int)


class TestFibFibMonotonicity:
    def test_non_decreasing_from_index_two(self):
        # From n=2 onward all terms are non-negative and non-decreasing
        values = [fibfib(n) for n in range(2, 25)]
        assert all(values[i] <= values[i + 1] for i in range(len(values) - 1))

    def test_non_negative_values(self):
        for n in range(0, 25):
            assert fibfib(n) >= 0
