import pytest

from solution import count_upper


class TestCountUpperExamples:
    """Tests based on the examples given in the docstring."""

    def test_example_one(self):
        assert count_upper('aBCdEf') == 1

    def test_example_two(self):
        assert count_upper('abcdefg') == 0

    def test_example_three(self):
        assert count_upper('dBBE') == 0


class TestCountUpperEdgeCases:
    def test_empty_string(self):
        assert count_upper('') == 0

    def test_single_uppercase_vowel(self):
        assert count_upper('A') == 1

    def test_single_lowercase_vowel(self):
        assert count_upper('a') == 0

    def test_single_uppercase_consonant(self):
        assert count_upper('B') == 0

    def test_single_lowercase_consonant(self):
        assert count_upper('b') == 0


class TestCountUpperPositionSensitivity:
    def test_all_uppercase_vowels_on_even_indices(self):
        # indices: 0=A,1=x,2=E,3=x,4=I,5=x,6=O,7=x,8=U
        assert count_upper('AxExIxOxU') == 5

    def test_uppercase_vowels_only_on_odd_indices_dont_count(self):
        # indices: 0=x,1=A,2=x,3=E,4=x,5=I,6=x,7=O,8=x,9=U
        assert count_upper('xAxExIxOxU') == 0

    def test_lowercase_vowels_on_even_indices_dont_count(self):
        assert count_upper('aecho') == 0

    def test_uppercase_consonants_on_even_indices_dont_count(self):
        assert count_upper('BxCxDxFxG') == 0

    def test_mixed_case_only_even_uppercase_vowels_counted(self):
        # 'ABCDEFGHI' -> even indices: A(0), C(2), E(4), G(6), I(8)
        # uppercase vowels among these: A, E, I -> 3
        assert count_upper('ABCDEFGHI') == 3


class TestCountUpperNonAlphaCharacters:
    def test_digits_and_symbols_ignored(self):
        assert count_upper('1E2I3O4U') == 0

    def test_vowel_like_symbols_not_counted(self):
        assert count_upper('@A#E$I') == 1  # only 'A' at index 1... verify below

    def test_uppercase_vowels_surrounded_by_symbols(self):
        # indices: 0='#',1='A',2='!',3='E' -> even indices are '#','!' -> no vowels
        assert count_upper('#A!E') == 0


class TestCountUpperLongerStrings:
    def test_repeated_pattern(self):
        s = 'AaEeIiOoUu' * 3
        # In 'AaEeIiOoUu', even indices (0,2,4,6,8) are A,E,I,O,U -> 5 uppercase vowels
        # Each repetition is 10 chars long (even length), so pattern repeats identically
        assert count_upper(s) == 15

    def test_no_vowels_at_all(self):
        assert count_upper('bcdfg BCDFG bcdfg') == 0

    def test_all_uppercase_string(self):
        assert count_upper('AEIOUAEIOU') == 5


if __name__ == '__main__':
    import sys
    sys.exit(pytest.main([__file__, '-v']))
