import pytest

from solution import odd_count

TEMPLATE = "the number of odd elements in the string i of the input."


def expected_line(count):
    """Build the expected output line the same way the spec's examples do:
    every literal 'i' in the template is replaced by the odd-digit count."""
    return TEMPLATE.replace("i", str(count))


def count_odd_digits(s):
    """Independent (non-lambda/filter based) reference implementation used
    only to compute expected odd-digit counts for assertions."""
    return sum(1 for ch in s if int(ch) % 2 == 1)


class TestOddCountDocstringExamples:
    def test_docstring_example_single_string(self):
        assert odd_count(['1234567']) == [
            "the number of odd elements 4n the str4ng 4 of the 4nput."
        ]

    def test_docstring_example_multiple_strings(self):
        assert odd_count(['3', "11111111"]) == [
            "the number of odd elements 1n the str1ng 1 of the 1nput.",
            "the number of odd elements 8n the str8ng 8 of the 8nput.",
        ]


class TestOddCountEdgeCases:
    def test_empty_list_returns_empty_list(self):
        assert odd_count([]) == []

    def test_empty_string_has_zero_odd_digits(self):
        assert odd_count(['']) == [expected_line(0)]

    def test_all_even_digits(self):
        assert odd_count(['2468']) == [expected_line(0)]

    def test_single_zero_digit(self):
        assert odd_count(['0']) == [expected_line(0)]

    def test_all_odd_digits(self):
        assert odd_count(['13579']) == [expected_line(5)]

    def test_double_digit_count_replacement(self):
        # 10 odd digits -> count is "10", exercising multi-character replacement.
        s = '1' * 10
        assert odd_count([s]) == [expected_line(10)]


class TestOddCountBehavior:
    def test_multiple_strings_preserve_order_and_values(self):
        inputs = ['4', '135', '22', '999']
        result = odd_count(inputs)
        expected = [expected_line(count_odd_digits(s)) for s in inputs]
        assert result == expected

    def test_output_length_matches_input_length(self):
        inputs = ['1', '22', '333', '4444', '55555']
        assert len(odd_count(inputs)) == len(inputs)

    def test_return_type_is_list_of_strings(self):
        result = odd_count(['12'])
        assert isinstance(result, list)
        assert all(isinstance(item, str) for item in result)

    def test_does_not_mutate_input_list(self):
        inputs = ['123', '456']
        inputs_snapshot = list(inputs)
        odd_count(inputs)
        assert inputs == inputs_snapshot


class TestOddCountVariousCounts:
    @pytest.mark.parametrize("s,count", [
        ('1', 1),
        ('2', 0),
        ('9', 1),
        ('123456789', 5),
        ('0000000000', 0),
        ('02468', 0),
        ('13579', 5),
    ])
    def test_various_digit_strings(self, s, count):
        assert odd_count([s]) == [expected_line(count)]
