from solution import select_words


class TestProvidedExamples:
    def test_mary_had_a_little_lamb_n4(self):
        assert select_words("Mary had a little lamb", 4) == ["little"]

    def test_mary_had_a_little_lamb_n3(self):
        assert select_words("Mary had a little lamb", 3) == ["Mary", "lamb"]

    def test_simple_white_space_n2(self):
        assert select_words("simple white space", 2) == []

    def test_hello_world_n4(self):
        assert select_words("Hello world", 4) == ["world"]

    def test_uncle_sam_n3(self):
        assert select_words("Uncle sam", 3) == ["Uncle"]


class TestEmptyString:
    def test_empty_string_returns_empty_list(self):
        assert select_words("", 0) == []

    def test_empty_string_any_n(self):
        assert select_words("", 4) == []


class TestNoMatches:
    def test_no_words_match_consonant_count(self):
        assert select_words("Mary had a little lamb", 10) == []

    def test_high_n_no_matches(self):
        assert select_words("cat dog", 100) == []


class TestZeroConsonants:
    def test_n_zero_matches_all_vowel_words(self):
        # "a" has 0 consonants, "I" has 0 consonants
        assert select_words("a I ate", 0) == ["a", "I"]

    def test_n_zero_no_all_vowel_words(self):
        assert select_words("cat dog", 0) == []


class TestSingleWord:
    def test_single_word_matching(self):
        assert select_words("rhythm", 6) == ["rhythm"]

    def test_single_word_not_matching(self):
        assert select_words("rhythm", 3) == []


class TestCaseSensitivity:
    def test_uppercase_vowels_not_counted_as_consonants(self):
        # "AEIOU" -> 0 consonants
        assert select_words("AEIOU bcdfg", 0) == ["AEIOU"]

    def test_mixed_case_consonant_counting(self):
        # "Xyz" -> X, z consonants ('y' also consonant) => 3 consonants
        assert select_words("Xyz ab", 3) == ["Xyz"]


class TestMultipleMatches:
    def test_multiple_words_same_consonant_count_in_order(self):
        assert select_words("cat bat hat", 2) == ["cat", "bat", "hat"]

    def test_order_preserved(self):
        result = select_words("Mary had a little lamb", 3)
        assert result == ["Mary", "lamb"]
        assert result.index("Mary") < result.index("lamb")


class TestWhitespaceHandling:
    def test_multiple_spaces_between_words_ignored(self):
        # extra spaces produce empty strings internally which must be filtered out
        assert select_words("cat  dog", 3) == ["cat", "dog"]

    def test_leading_and_trailing_spaces(self):
        assert select_words(" cat dog ", 3) == ["cat", "dog"]


class TestReturnType:
    def test_returns_list_type(self):
        assert isinstance(select_words("Mary had a little lamb", 4), list)

    def test_returns_list_of_strings(self):
        result = select_words("Mary had a little lamb", 3)
        assert all(isinstance(word, str) for word in result)


@pytest.mark.parametrize(
    "s, n, expected",
    [
        ("Mary had a little lamb", 4, ["little"]),
        ("Mary had a little lamb", 3, ["Mary", "lamb"]),
        ("simple white space", 2, []),
        ("Hello world", 4, ["world"]),
        ("Uncle sam", 3, ["Uncle"]),
        ("", 0, []),
        ("a", 0, ["a"]),
        ("b", 1, ["b"]),
    ],
)
def test_parametrized_cases(s, n, expected):
    assert select_words(s, n) == expected
