import pytest

from solution import get_odd_collatz


def reference_collatz_odds(n):
    """Independent reference implementation used to cross-check get_odd_collatz."""
    seq = [n]
    x = n
    while x != 1:
        x = x // 2 if x % 2 == 0 else x * 3 + 1
        seq.append(x)
    return sorted({v for v in seq if v % 2 == 1})


class TestKnownValues:
    """Known-answer tests (values verified against the documented example and
    hand-traced Collatz sequences)."""

    def test_example_from_docstring(self):
        assert get_odd_collatz(5) == [1, 5]

    def test_n_equals_one(self):
        assert get_odd_collatz(1) == [1]

    def test_n_equals_two(self):
        # 2 -> 1 ; only odd number encountered is 1
        assert get_odd_collatz(2) == [1]

    def test_n_equals_three(self):
        # 3 -> 10 -> 5 -> 16 -> 8 -> 4 -> 2 -> 1
        assert get_odd_collatz(3) == [1, 3, 5]

    def test_n_equals_four(self):
        # 4 -> 2 -> 1
        assert get_odd_collatz(4) == [1]

    def test_n_equals_twelve(self):
        # 12 -> 6 -> 3 -> 10 -> 5 -> 16 -> 8 -> 4 -> 2 -> 1
        assert get_odd_collatz(12) == [1, 3, 5]

    def test_n_equals_fourteen(self):
        # 14 -> 7 -> 22 -> 11 -> 34 -> 17 -> 52 -> 26 -> 13 -> 40 -> 20 -> 10
        # -> 5 -> 16 -> 8 -> 4 -> 2 -> 1
        assert get_odd_collatz(14) == [1, 5, 7, 11, 13, 17]

    def test_n_is_power_of_two(self):
        # Powers of two collapse straight down to 1; only odd value is 1
        assert get_odd_collatz(16) == [1]
        assert get_odd_collatz(64) == [1]

    def test_odd_starting_value_included(self):
        result = get_odd_collatz(7)
        assert 7 in result
        assert result[0] == 1


class TestStructuralProperties:
    """Properties that must hold for any valid positive integer input."""

    @pytest.mark.parametrize("n", list(range(1, 200)))
    def test_all_elements_are_odd(self, n):
        result = get_odd_collatz(n)
        assert all(v % 2 == 1 for v in result)

    @pytest.mark.parametrize("n", list(range(1, 200)))
    def test_result_is_sorted_ascending(self, n):
        result = get_odd_collatz(n)
        assert result == sorted(result)

    @pytest.mark.parametrize("n", list(range(1, 200)))
    def test_one_is_always_present(self, n):
        assert 1 in get_odd_collatz(n)

    @pytest.mark.parametrize("n", list(range(1, 200)))
    def test_no_duplicate_values(self, n):
        result = get_odd_collatz(n)
        assert len(result) == len(set(result))

    @pytest.mark.parametrize("n", list(range(1, 200)))
    def test_return_type_is_list(self, n):
        assert isinstance(get_odd_collatz(n), list)

    def test_odd_input_is_present_in_output(self):
        for n in range(1, 100, 2):
            assert n in get_odd_collatz(n)


class TestAgainstReferenceImplementation:
    """Cross-check against an independently written reference implementation."""

    @pytest.mark.parametrize("n", list(range(1, 300)))
    def test_matches_reference(self, n):
        assert get_odd_collatz(n) == reference_collatz_odds(n)

    def test_matches_reference_for_larger_values(self):
        for n in (500, 837, 1023, 2**10, 6171):
            assert get_odd_collatz(n) == reference_collatz_odds(n)


class TestLargerInputs:
    def test_large_n_terminates_and_is_well_formed(self):
        result = get_odd_collatz(27)  # famously long Collatz chain
        assert isinstance(result, list)
        assert result == sorted(result)
        assert all(v % 2 == 1 for v in result)
        assert 1 in result
        assert 27 in result

    def test_very_large_power_of_two(self):
        assert get_odd_collatz(2**20) == [1]
