import pytest

from solution import split_words


class TestSplitOnWhitespace:
    def test_basic_space(self):
        assert split_words("Hello world!") == ["Hello", "world!"]

    def test_multiple_words(self):
        assert split_words("The quick brown fox") == ["The", "quick", "brown", "fox"]

    def test_tab_character(self):
        assert split_words("a\tb\tc") == ["a", "b", "c"]

    def test_newline_character(self):
        assert split_words("a\nb\nc") == ["a", "b", "c"]

    def test_carriage_return_character(self):
        assert split_words("a\rb\rc") == ["a", "b", "c"]

    def test_whitespace_takes_priority_over_comma(self):
        # Contains both a space and commas -> whitespace rule wins
        assert split_words("a, b,c") == ["a,", "b,c"]

    def test_single_word_no_split_needed(self):
        assert split_words("hello world") == ["hello", "world"]


class TestSplitOnComma:
    def test_basic_comma(self):
        assert split_words("Hello,world!") == ["Hello", "world!"]

    def test_multiple_commas(self):
        assert split_words("a,b,c") == ["a", "b", "c"]

    def test_comma_with_empty_segments(self):
        assert split_words("a,,b") == ["a", "", "b"]

    def test_trailing_comma(self):
        assert split_words("a,b,") == ["a", "b", ""]


class TestCountOddLowercaseLetters:
    def test_example_abcdef(self):
        # a(0)e,b(1)o,c(2)e,d(3)o,e(4)e,f(5)o -> b,d,f odd => 3
        assert split_words("abcdef") == 3

    def test_all_odd_letters(self):
        # b(1), d(3), f(5), h(7), j(9) -> all odd
        assert split_words("bdfhj") == 5

