        assert sorted_list_sum([]) == []

    def test_all_odd_length_removed(self):
        assert sorted_list_sum(["a", "abc", "abcde"]) == []

    def test_all_even_length_kept(self):
        assert sorted_list_sum(["cd", "ab"]) == ["ab", "cd"]

    def test_sorted_by_length_ascending(self):
        assert sorted_list_sum(["abcdef", "ab", "abcd"]) == ["ab", "abcd", "abcdef"]

