class TestFilterIntegers:
    def test_mixed_types_returns_only_integers(self):
        assert filter_integers(['a', 3.14, 5]) == [5]

    def test_docstring_example_two(self):
        assert filter_integers([1, 2, 3, 'abc', {}, []]) == [1, 2, 3]

    def test_empty_list_returns_empty_list(self):
        assert filter_integers([]) == []

    def test_all_integers_returns_all(self):
        assert filter_integers([1, 2, 3, -4, 0]) == [1, 2, 3, -4, 0]

    def test_no_integers_returns_empty_list(self):
        assert filter_integers(['a', 'b', 3.14, None, {}, [], (1, 2)]) == []

    def test_excludes_booleans_despite_being_int_subclass(self):
        # type(x) == int is strict, so bool (a subclass of int) must be excluded.
        assert filter_integers([True, False, 1, 0]) == [1, 0]

    def test_excludes_floats(self):
        assert filter_integers([1.0, 2.5, -3.9]) == []

    def test_excludes_strings_that_look_like_integers(self):
        assert filter_integers(['1', '2', '3']) == []

    def test_excludes_none(self):
        assert filter_integers([None, 1, None, 2]) == [1, 2]

    def test_excludes_complex_numbers(self):
        assert filter_integers([1 + 2j, 3]) == [3]

    def test_excludes_containers(self):
        assert filter_integers([[1, 2], {'a': 1}, (1,), {1, 2}, 5]) == [5]

    def test_negative_integers_included(self):
        assert filter_integers([-1, -2, -3]) == [-1, -2, -3]

    def test_large_integers_included(self):
        big = 10 ** 30
        assert filter_integers([big, 1]) == [big, 1]

    def test_preserves_order(self):
        assert filter_integers([5, 'x', 3, 'y', 1]) == [5, 3, 1]

    def test_does_not_mutate_input_list(self):
        original = [1, 'a', 2]
        original_copy = list(original)
        filter_integers(original)
        assert original == original_copy

    def test_return_type_is_list(self):
        result = filter_integers([1, 2, 3])
        assert isinstance(result, list)

    def test_excludes_custom_int_subclass_instances(self):
        class MyInt(int):
            pass

        # type(x) == int excludes subclasses, unlike isinstance.
        assert filter_integers([MyInt(5), 5]) == [5]

    @pytest.mark.parametrize(
        "values, expected",
        [
            ([], []),
            ([1], [1]),
            (['a'], []),
            ([1, True, False, 2], [1, 2]),
            ([None, 1.5, 'x', {}, [], (), set()], []),
        ],
    )
    def test_parametrized_cases(self, values, expected):
        assert filter_integers(values) == expected
