import pytest

from solution import by_length


class TestByLength:
    def test_example_from_docstring(self):
        arr = [2, 1, 1, 4, 5, 8, 2, 3]
        assert by_length(arr) == [
            "Eight", "Five", "Four", "Three", "Two", "Two", "One", "One",
        ]

    def test_empty_array_returns_empty_list(self):
        assert by_length([]) == []

    def test_ignores_out_of_range_numbers(self):
        arr = [1, -1, 55]
        assert by_length(arr) == ["One"]

    def test_ignores_zero(self):
        assert by_length([0, 1]) == ["One"]

    def test_ignores_negative_numbers(self):
        assert by_length([-5, -1, -100]) == []

    def test_ignores_numbers_greater_than_nine(self):
        assert by_length([10, 20, 100]) == []

    def test_all_numbers_out_of_range_returns_empty(self):
        assert by_length([0, -3, 10, 99]) == []

    def test_single_valid_digit(self):
        assert by_length([7]) == ["Seven"]

    def test_boundary_value_one(self):
        assert by_length([1]) == ["One"]

    def test_boundary_value_nine(self):
        assert by_length([9]) == ["Nine"]

    def test_boundary_just_below_one_excluded(self):
        # 0 should be excluded, only valid values remain
        assert by_length([0, 5]) == ["Five"]

    def test_boundary_just_above_nine_excluded(self):
        assert by_length([10, 5]) == ["Five"]

    def test_all_digits_one_through_nine_sorted_descending(self):
        arr = [5, 3, 1, 9, 7, 2, 8, 6, 4]
        assert by_length(arr) == [
            "Nine", "Eight", "Seven", "Six", "Five",
            "Four", "Three", "Two", "One",
        ]

    def test_duplicates_preserved(self):
        arr = [3, 3, 3]
        assert by_length(arr) == ["Three", "Three", "Three"]

    def test_already_sorted_ascending_input(self):
        arr = [1, 2, 3, 4, 5]
        assert by_length(arr) == ["Five", "Four", "Three", "Two", "One"]

    def test_already_sorted_descending_input(self):
        arr = [5, 4, 3, 2, 1]
        assert by_length(arr) == ["Five", "Four", "Three", "Two", "One"]

    def test_mixed_valid_and_invalid_values(self):
        arr = [15, 2, -3, 8, 0, 4, 42]
        assert by_length(arr) == ["Eight", "Four", "Two"]

    def test_does_not_mutate_input_array(self):
        arr = [3, 1, 2]
        original_copy = list(arr)
        by_length(arr)
        assert arr == original_copy

    def test_return_type_is_list(self):
        result = by_length([1, 2, 3])
        assert isinstance(result, list)

    def test_return_elements_are_strings(self):
        result = by_length([1, 2, 3])
        assert all(isinstance(item, str) for item in result)

    @pytest.mark.parametrize(
        "value,expected_word",
        [
            (1, "One"),
            (2, "Two"),
            (3, "Three"),
            (4, "Four"),
            (5, "Five"),
            (6, "Six"),
            (7, "Seven"),
            (8, "Eight"),
            (9, "Nine"),
        ],
    )
    def test_each_digit_maps_to_correct_word(self, value, expected_word):
        assert by_length([value]) == [expected_word]

    def test_large_array_with_repeats_and_noise(self):
        arr = [9, 9, -50, 1, 1, 1, 100, 5, 0, 3]
        assert by_length(arr) == [
            "Nine", "Nine", "Five", "Three", "One", "One", "One",
        ]
