import pytest

from solution import split_words


class TestSplitWordsWhitespace:
    """When the input contains any whitespace character, split on whitespace."""

    def test_docstring_example_space(self):
        assert split_words("Hello world!") == ["Hello", "world!"]

    def test_splits_on_single_space(self):
        assert split_words("foo bar baz") == ["foo", "bar", "baz"]

    def test_collapses_multiple_spaces(self):
        assert split_words("foo   bar") == ["foo", "bar"]

    def test_splits_on_tab(self):
        assert split_words("foo\tbar") == ["foo", "bar"]

    def test_splits_on_newline(self):
        assert split_words("foo\nbar") == ["foo", "bar"]

    def test_splits_on_carriage_return(self):
        assert split_words("foo\rbar") == ["foo", "bar"]

    def test_strips_leading_and_trailing_whitespace(self):
        assert split_words("  foo bar  ") == ["foo", "bar"]

    def test_whitespace_takes_priority_over_comma(self):
        # Contains both a space and a comma -> whitespace branch wins.
        assert split_words("foo,bar baz,qux") == ["foo,bar", "baz,qux"]

    def test_only_whitespace_returns_empty_list(self):
        assert split_words("   ") == []

    def test_mixed_whitespace_types(self):
        assert split_words("foo\tbar\nbaz qux") == ["foo", "bar", "baz", "qux"]


class TestSplitWordsComma:
    """When there is no whitespace but a comma exists, split on commas."""

    def test_docstring_example_comma(self):
        assert split_words("Hello,world!") == ["Hello", "world!"]

    def test_splits_on_multiple_commas(self):
        assert split_words("a,b,c") == ["a", "b", "c"]

    def test_consecutive_commas_produce_empty_strings(self):
        assert split_words("a,,b") == ["a", "", "b"]

    def test_leading_and_trailing_comma(self):
        assert split_words(",a,b,") == ["", "a", "b", ""]

    def test_single_comma_only(self):
        assert split_words(",") == ["", ""]


class TestSplitWordsOddLetterCount:
    """When there is no whitespace and no comma, count lower-case letters
    whose position in the alphabet (0-indexed) is odd."""

    def test_docstring_example_abcdef(self):
        assert split_words("abcdef") == 3

    def test_empty_string_returns_zero(self):
        assert split_words("") == 0

    def test_no_letters_returns_zero(self):
        assert split_words("12345!?") == 0

    def test_all_uppercase_letters_ignored(self):
        assert split_words("ABCDEF") == 0

    def test_mixed_case_only_counts_lowercase(self):
        # lower letters: b(1,odd) d(3,odd) f(5,odd) -> 3
        assert split_words("AbCdEf") == 3

    def test_full_lowercase_alphabet(self):
        # odd-indexed letters: b,d,f,h,j,l,n,p,r,t,v,x,z -> 13
        assert split_words("abcdefghijklmnopqrstuvwxyz") == 13

    def test_only_even_indexed_letters(self):
        # a,c,e,g,i,k,m,o,q,s,u,w,y are all even-order -> 0
        assert split_words("acegikmoqsuwy") == 0

    def test_only_odd_indexed_letters(self):
        assert split_words("bdfhjlnprtvxz") == 13

