    def test_triple_duplicate_returns_false_even_if_ascending(self):
        assert is_sorted([1, 2, 2, 2, 3, 4]) is False


class TestIsSortedEdgeCases:
    def test_empty_list_is_sorted(self):
        assert is_sorted([]) is True

