        result = sorted_list_sum(["ab", "cd", "abcd"])
        assert result == ["ab", "cd", "abcd"]

    def test_empty_string_is_even_length_and_kept(self):
        assert sorted_list_sum(["", "a"]) == [""]

    def test_mixed_lengths_filters_correctly(self):
        assert sorted_list_sum(["x", "xx", "xxx", "xxxx", "xxxxx"]) == ["xx", "xxxx"]


class TestSortedListSumOrdering:
