        result = sorted_list_sum(["abcdef", "ab", "abcd"])
        assert result == ["ab", "abcd", "abcdef"]

    def test_sorts_alphabetically_when_same_length(self):
        result = sorted_list_sum(["dc", "ba", "zz", "aa"])
        assert result == ["aa", "ba", "dc", "zz"]

    def test_sorts_by_length_first_then_alphabetically(self):
        result = sorted_list_sum(["bb", "aaaa", "aa", "cccc"])
        assert result == ["aa", "bb", "aaaa", "cccc"]

