        result = sorted_list_sum(["aa", "aa", "bb"])
        assert result == ["aa", "aa", "bb"]

    def test_duplicates_with_mixed_lengths(self):
        result = sorted_list_sum(["abcd", "ab", "ab", "a", "abcd"])
        assert result == ["ab", "ab", "abcd", "abcd"]


class TestSortedListSumEdgeCases:
    def test_empty_list_returns_empty_list(self):
        assert sorted_list_sum([]) == []

    def test_all_odd_length_returns_empty_list(self):
        assert sorted_list_sum(["a", "abc", "abcde", "abcdefg"]) == []

    def test_single_even_length_element(self):
        assert sorted_list_sum(["xy"]) == ["xy"]

    def test_single_odd_length_element(self):
        assert sorted_list_sum(["x"]) == []

    def test_does_not_mutate_input_list(self):
        original = ["ab", "a", "cd"]
        original_copy = list(original)
        sorted_list_sum(original)
        assert original == original_copy

    def test_return_type_is_list(self):
        result = sorted_list_sum(["ab", "a"])
        assert isinstance(result, list)

    def test_case_sensitive_alphabetical_sort(self):
        # Uppercase letters sort before lowercase in standard string comparison
        result = sorted_list_sum(["ba", "Ab", "AB", "ab"])
        assert result == sorted(["ba", "Ab", "AB", "ab"])
