        assert x_or_y(97, "prime", "composite") == "prime"

    def test_prime_returns_x_even_when_x_is_falsy(self):
        # Ensure the branch chosen is based on primality, not truthiness of x/y.
        assert x_or_y(5, 0, "y") == 0

    def test_prime_with_none_as_y(self):
        assert x_or_y(11, "x", None) == "x"


class TestXOrYWithCompositeOrNonPrimeN:
