from solution import x_or_y


class TestXOrYWithPrimeN:
    """Cases where n is prime -> should return x."""

    def test_small_prime_two(self):
        assert x_or_y(2, "X", "Y") == "X"

    def test_small_prime_three(self):
        assert x_or_y(3, "X", "Y") == "X"

    def test_prime_seven_matches_docstring_example(self):
        assert x_or_y(7, 34, 12) == 34

    def test_prime_thirteen(self):
        assert x_or_y(13, "prime", "composite") == "prime"

    def test_larger_prime_ninety_seven(self):
        assert x_or_y(97, "prime", "composite") == "prime"

    def test_prime_returns_x_even_when_x_is_falsy(self):
        # Ensure the branch chosen is based on primality, not truthiness of x/y.
        assert x_or_y(5, 0, "y") == 0

    def test_prime_with_none_as_y(self):
        assert x_or_y(11, "x", None) == "x"


class TestXOrYWithCompositeOrNonPrimeN:
    """Cases where n is not prime -> should return y."""

    def test_composite_fifteen_matches_docstring_example(self):
        assert x_or_y(15, 8, 5) == 5

    def test_composite_four(self):
        assert x_or_y(4, "X", "Y") == "Y"

    def test_composite_nine(self):
        assert x_or_y(9, "X", "Y") == "Y"

    def test_composite_hundred(self):
        assert x_or_y(100, "X", "Y") == "Y"

    def test_zero_is_not_prime(self):
        assert x_or_y(0, "X", "Y") == "Y"

    def test_one_is_not_prime(self):
        assert x_or_y(1, "X", "Y") == "Y"

    def test_negative_number_is_not_prime(self):
        assert x_or_y(-7, "X", "Y") == "Y"

    def test_non_prime_returns_y_even_when_y_is_falsy(self):
        assert x_or_y(8, "x", 0) == 0

    def test_non_prime_with_none_as_x(self):
        assert x_or_y(6, None, "y") == "y"


class TestXOrYReturnValueIdentity:
    """The function should return the exact object passed in, unchanged."""

    def test_returns_same_object_for_x(self):
        sentinel = object()
        assert x_or_y(2, sentinel, "y") is sentinel

    def test_returns_same_object_for_y(self):
        sentinel = object()
        assert x_or_y(4, "x", sentinel) is sentinel


@pytest.mark.parametrize(
    "n,expected_branch",
    [
        (2, "x"),
        (3, "x"),
        (5, "x"),
        (7, "x"),
        (11, "x"),
        (13, "x"),
        (17, "x"),
        (19, "x"),
        (23, "x"),
        (0, "y"),
        (1, "y"),
        (4, "y"),
        (6, "y"),
        (8, "y"),
        (9, "y"),
        (10, "y"),
        (21, "y"),
        (25, "y"),
    ],
)
def test_x_or_y_parametrized_primality(n, expected_branch):
    result = x_or_y(n, "x", "y")
    assert result == expected_branch

