from solution import truncate_number


class TestTruncateNumberBasic:
    def test_docstring_example(self):
        assert truncate_number(3.5) == 0.5

    def test_simple_decimal(self):
        assert truncate_number(1.33) == pytest.approx(0.33)

    def test_multi_digit_integer_part(self):
        assert truncate_number(123.456) == pytest.approx(0.456)

    def test_only_decimal_part_below_one(self):
        # number is already smaller than 1, int() truncates to 0
        assert truncate_number(0.5) == 0.5

    def test_small_fractional_value(self):
        assert truncate_number(0.1) == pytest.approx(0.1)


class TestTruncateNumberIntegerValued:
    def test_zero(self):
        assert truncate_number(0.0) == 0.0

    def test_whole_number_float(self):
        assert truncate_number(5.0) == 0.0

    def test_one(self):
        assert truncate_number(1.0) == 0.0

    def test_large_whole_number_float(self):
        assert truncate_number(1000.0) == 0.0


class TestTruncateNumberPrecision:
    def test_result_is_less_than_one(self):
        result = truncate_number(42.789)
        assert 0 <= result < 1

    def test_result_type_is_float(self):
        assert isinstance(truncate_number(7.25), float)

    def test_repeated_call_consistency(self):
        # Function should be deterministic / side-effect free.
        assert truncate_number(9.81) == truncate_number(9.81)

    def test_integer_part_plus_decimal_reconstructs_number(self):
        number = 314.159
        decimal = truncate_number(number)
        assert int(number) + decimal == pytest.approx(number)

    @pytest.mark.parametrize(
        "number, expected",
        [
            (3.5, 0.5),
            (2.25, 0.25),
            (10.75, 0.75),
            (100.999999, 0.999999),
            (7.0625, 0.0625),
        ],
    )
    def test_parametrized_values(self, number, expected):
        assert truncate_number(number) == pytest.approx(expected)


class TestTruncateNumberEdgeCases:
    def test_very_small_decimal(self):
        assert truncate_number(5.0000001) == pytest.approx(0.0000001)

    def test_very_close_to_next_integer(self):
        assert truncate_number(6.9999999) == pytest.approx(0.9999999)

    def test_large_number_with_decimal(self):
        result = truncate_number(987654321.125)
        assert result == pytest.approx(0.125)

    def test_no_nan_or_inf_produced(self):
        result = truncate_number(17.5)
        assert not math.isnan(result)
        assert not math.isinf(result)
