import pytest

from solution import how_many_times


class TestHowManyTimesDocstringExamples:
    def test_empty_string_returns_zero(self):
        assert how_many_times('', 'a') == 0

    def test_single_char_substring_no_overlap(self):
        assert how_many_times('aaa', 'a') == 3

    def test_overlapping_substring(self):
        assert how_many_times('aaaa', 'aa') == 3


class TestHowManyTimesNoMatches:
    def test_substring_not_present(self):
        assert how_many_times('hello', 'x') == 0

    def test_substring_longer_than_string(self):
        assert how_many_times('ab', 'abc') == 0

    def test_substring_not_present_in_longer_string(self):
        assert how_many_times('abcdef', 'xyz') == 0


class TestHowManyTimesOverlapping:
    def test_overlapping_two_char_substring(self):
        assert how_many_times('aaaaa', 'aa') == 4

    def test_overlapping_three_char_substring(self):
        assert how_many_times('aaaaa', 'aaa') == 3

    def test_overlapping_pattern_bbb(self):
        assert how_many_times('bbbb', 'bb') == 3

    def test_overlapping_repeated_pattern(self):
        # 'ababab' -> occurrences of 'aba' at index 0 and 2 (overlap)
        assert how_many_times('ababab', 'aba') == 2


class TestHowManyTimesNonOverlapping:
    def test_non_overlapping_pattern(self):
        assert how_many_times('abcabcabc', 'abc') == 3

    def test_single_occurrence(self):
        assert how_many_times('hello world', 'world') == 1

    def test_substring_at_start(self):
        assert how_many_times('abcdef', 'abc') == 1

    def test_substring_at_end(self):
        assert how_many_times('defabc', 'abc') == 1


class TestHowManyTimesEdgeCases:
    def test_string_equals_substring(self):
        assert how_many_times('abc', 'abc') == 1

    def test_empty_substring_matches_every_position(self):
        # startswith('') is True for every index, including the empty range
        assert how_many_times('abc', '') == 3

    def test_empty_substring_on_empty_string(self):
        assert how_many_times('', '') == 0

    def test_single_char_string_matching(self):
        assert how_many_times('a', 'a') == 1

    def test_single_char_string_not_matching(self):
        assert how_many_times('a', 'b') == 0

    def test_case_sensitivity(self):
        assert how_many_times('AAA', 'a') == 0

    def test_whitespace_substring(self):
        assert how_many_times('a b c  d', ' ') == 5

    def test_special_characters(self):
        assert how_many_times('a.b.c.d', '.') == 3

    def test_numeric_string(self):
        assert how_many_times('1212121', '121') == 3


@pytest.mark.parametrize(
    "string, substring, expected",
    [
        ('', 'a', 0),
        ('aaa', 'a', 3),
        ('aaaa', 'aa', 3),
        ('aaaaa', 'aa', 4),
        ('abcabcabc', 'abc', 3),
        ('mississippi', 'iss', 2),
        ('mississippi', 'ss', 2),
        ('mississippi', 'i', 4),
        ('xxxxx', 'xx', 4),
        ('no match here', 'zzz', 0),
    ],
)
def test_how_many_times_parametrized(string, substring, expected):
    assert how_many_times(string, substring) == expected
