import math

import pytest

from solution import filter_integers


class TestFilterIntegers:
    def test_docstring_example_mixed_str_float_int(self):
        assert filter_integers(['a', 3.14, 5]) == [5]

    def test_docstring_example_ints_with_other_types(self):
        assert filter_integers([1, 2, 3, 'abc', {}, []]) == [1, 2, 3]

    def test_empty_list_returns_empty_list(self):
        assert filter_integers([]) == []

    def test_all_integers_returned_unchanged(self):
        assert filter_integers([1, 2, 3, -4, 0]) == [1, 2, 3, -4, 0]

    def test_no_integers_returns_empty_list(self):
        assert filter_integers(['a', 'b', 3.14, None, [], {}, (1, 2)]) == []

    def test_excludes_floats(self):
        assert filter_integers([1.0, 2.5, -3.0]) == []

    def test_excludes_strings(self):
        assert filter_integers(['1', '2', 'three']) == []

    def test_excludes_none(self):
        assert filter_integers([None, None]) == []

    def test_bool_is_excluded_despite_being_int_subclass(self):
        # type(True) is bool, not int, so `type(x) == int` excludes booleans
        # even though bool is a subclass of int in Python.
        assert filter_integers([True, False]) == []

    def test_bool_excluded_among_real_integers(self):
        assert filter_integers([1, True, 2, False, 3]) == [1, 2, 3]

    def test_excludes_complex_numbers(self):
        assert filter_integers([1 + 2j, 3]) == [3]

    def test_excludes_lists_dicts_sets_tuples(self):
        assert filter_integers([[1], {'a': 1}, {1, 2}, (1,)]) == []

    def test_excludes_nested_containers_with_integers_inside(self):
        assert filter_integers([[1, 2], {'a': 1}, 5]) == [5]

    def test_preserves_order_of_original_list(self):
        assert filter_integers([5, 'a', 3, 'b', 1]) == [5, 3, 1]

    def test_preserves_duplicate_integers(self):
        assert filter_integers([1, 1, 2, 2, 3]) == [1, 1, 2, 2, 3]

    def test_large_and_negative_integers(self):
        big = 10 ** 20
        assert filter_integers([big, -big, 0]) == [big, -big, 0]

    def test_excludes_custom_class_instances(self):
        class Foo:
            pass

        assert filter_integers([Foo(), 42]) == [42]

    def test_excludes_int_like_subclass_instances(self):
        # A subclass of int has type() != int, so it should be excluded
        # under the implementation's strict `type(x) == int` check.
        class MyInt(int):
            pass

        assert filter_integers([MyInt(5), 5]) == [5]

    def test_excludes_nan_and_inf_floats(self):
        assert filter_integers([float('nan'), float('inf'), -float('inf')]) == []

    def test_excludes_bytes_and_bytearray(self):
        assert filter_integers([b'1', bytearray(b'2'), 3]) == [3]

    def test_return_type_is_list(self):
        result = filter_integers((x for x in []))
        assert isinstance(result, list)

    def test_accepts_generator_input(self):
        gen = (x for x in [1, 'a', 2.0, 2])
        assert filter_integers(gen) == [1, 2]

    def test_accepts_tuple_input(self):
        assert filter_integers((1, 'a', 2)) == [1, 2]

    def test_does_not_mutate_input_list(self):
        original = [1, 'a', 2, 3.0]
        original_copy = list(original)
