class TestCountUpper:
    def test_docstring_example_mixed(self):
        assert count_upper('aBCdEf') == 1

    def test_docstring_example_no_uppercase(self):
        assert count_upper('abcdefg') == 0

    def test_docstring_example_uppercase_at_odd_indices(self):
        assert count_upper('dBBE') == 0

    def test_empty_string(self):
        assert count_upper('') == 0

    def test_single_uppercase_vowel(self):
        assert count_upper('A') == 1

    def test_single_uppercase_consonant(self):
        assert count_upper('B') == 0

    def test_single_lowercase_vowel(self):
        assert count_upper('a') == 0

    def test_all_uppercase_vowels_at_even_indices(self):
        # indices 0,2,4,6,8 -> A,E,I,O,U all uppercase vowels
        assert count_upper('AxExIxOxU') == 5

    def test_uppercase_vowels_only_at_odd_indices_not_counted(self):
        # indices 1,3,5,7,9 hold uppercase vowels, even indices are 'x'
        assert count_upper('xAxExIxOxU') == 0

    def test_lowercase_vowels_at_even_indices_not_counted(self):
        assert count_upper('aecioux') == 0

    def test_all_five_uppercase_vowels_string(self):
        assert count_upper('AEIOU') == 3  # indices 0,2,4 -> A,I,U

    def test_repeated_uppercase_vowel_at_every_even_index(self):
        assert count_upper('AxAxAxA') == 4

    def test_uppercase_consonants_at_even_indices_not_counted(self):
        assert count_upper('BxDxFxG') == 0

    def test_mixed_case_vowels_and_consonants(self):
        assert count_upper('ABCDEfghIJKLmnop') == 2  # indices 0 'A', 8 'I'

    def test_non_alpha_characters_at_even_indices(self):
        assert count_upper('1E2O3U4') == 0

    def test_single_character_non_vowel_string_length_two(self):
        assert count_upper('EE') == 1  # only index 0 checked

    def test_length_two_uppercase_vowel_then_consonant(self):
        assert count_upper('OX') == 1

    def test_whitespace_and_uppercase_vowels(self):
        assert count_upper(' A E I ') == 0  # index0=' ', index2='A'... let's verify positions

    def test_all_uppercase_but_no_vowels(self):
        assert count_upper('BCDFG') == 0

    def test_long_alternating_string(self):
        s = 'AbEcIdOeUf'
        # indices: 0 A,2 E,4 I,6 O,8 U -> all vowels uppercase
        assert count_upper(s) == 5

    def test_case_sensitivity_lowercase_vowel_ignored(self):
        assert count_upper('aeiou') == 0

    def test_case_sensitivity_uppercase_vowel_counted(self):
        assert count_upper('AEIOUAEIOU') == 5  # indices 0,2,4,6,8 -> A,I,U,A,I

    @pytest.mark.parametrize(
        "s,expected",
        [
            ('', 0),
            ('A', 1),
            ('E', 1),
            ('I', 1),
            ('O', 1),
            ('U', 1),
            ('a', 0),
            ('Z', 0),
            ('AA', 1),
            ('EE', 1),
            ('AAAA', 2),
            ('ABCDEFGHIJ', 3),  # indices 0,2,4,6,8 -> A,C,E,G,I -> vowels: A,E,I = 3
        ],
    )
    def test_parametrized_cases(self, s, expected):
        assert count_upper(s) == expected
