    def test_comma_separated_no_spaces(self):
        assert words_string("apple,banana,cherry") == ["apple", "banana", "cherry"]

    def test_space_separated(self):
        assert words_string("apple banana cherry") == ["apple", "banana", "cherry"]

    def test_comma_and_space_mixed(self):
        assert words_string("apple, banana,cherry ,date") == [
            "apple",
            "banana",
            "cherry",
            "date",
        ]

    def test_single_word(self):
        assert words_string("hello") == ["hello"]

    def test_single_word_with_trailing_comma(self):
        assert words_string("hello,") == ["hello"]


class TestEmptyAndWhitespaceInputs:
    def test_empty_string(self):
        assert words_string("") == []

    def test_only_spaces(self):
        assert words_string("   ") == []

    def test_only_commas(self):
        assert words_string(",,,") == []

    def test_only_commas_and_spaces(self):
        assert words_string(" , , , ") == []


class TestExtraWhitespaceAndCommas:
    def test_multiple_consecutive_spaces(self):
        assert words_string("apple    banana") == ["apple", "banana"]

    def test_multiple_consecutive_commas(self):
        assert words_string("apple,,,,banana") == ["apple", "banana"]

    def test_comma_followed_by_multiple_spaces(self):
        assert words_string("apple,   banana") == ["apple", "banana"]

    def test_leading_and_trailing_whitespace(self):
        assert words_string("  apple banana  ") == ["apple", "banana"]

    def test_leading_and_trailing_commas(self):
        assert words_string(",apple,banana,") == ["apple", "banana"]

    def test_leading_and_trailing_mixed(self):
        assert words_string(" , apple, banana , ") == ["apple", "banana"]


class TestOtherWhitespaceCharacters:
    def test_tabs_and_newlines_are_treated_as_separators(self):
        assert words_string("apple\tbanana\ncherry") == ["apple", "banana", "cherry"]

    def test_mixed_tabs_newlines_commas_spaces(self):
        assert words_string("apple,\tbanana\n cherry") == ["apple", "banana", "cherry"]


