import pytest

from solution import split_words


class TestWhitespaceSplitting:
    def test_simple_space_split(self):
        assert split_words("Hello world!") == ["Hello", "world!"]

    def test_multiple_words(self):
        assert split_words("The quick brown fox") == ["The", "quick", "brown", "fox"]

    def test_collapses_multiple_spaces(self):
        assert split_words("Hello    world!") == ["Hello", "world!"]

    def test_strips_leading_and_trailing_whitespace(self):
        assert split_words("   Hello world!   ") == ["Hello", "world!"]

    def test_splits_on_tab(self):
        assert split_words("Hello\tworld!") == ["Hello", "world!"]

    def test_splits_on_newline(self):
        assert split_words("Hello\nworld!") == ["Hello", "world!"]

    def test_splits_on_carriage_return(self):
        assert split_words("Hello\rworld!") == ["Hello", "world!"]

    def test_mixed_whitespace_characters(self):
        assert split_words("Hello\t\nworld!\r foo") == ["Hello", "world!", "foo"]

    def test_whitespace_takes_precedence_over_comma(self):
        # Contains both a space and commas -> whitespace branch wins.
        assert split_words("Hello, world!") == ["Hello,", "world!"]

    def test_single_word_with_surrounding_whitespace_only(self):
        assert split_words("  Hello  ") == ["Hello"]


class TestCommaSplitting:
    def test_simple_comma_split(self):
        assert split_words("Hello,world!") == ["Hello", "world!"]

    def test_multiple_commas(self):
        assert split_words("a,b,c,d") == ["a", "b", "c", "d"]

    def test_consecutive_commas_produce_empty_strings(self):
        assert split_words("a,,b") == ["a", "", "b"]

    def test_leading_and_trailing_commas(self):
        assert split_words(",Hello,world!,") == ["", "Hello", "world!", ""]

    def test_single_comma_only(self):
        assert split_words(",") == ["", ""]


class TestOddLetterCounting:
    def test_example_abcdef(self):
        # a=0(even) b=1(odd) c=2(even) d=3(odd) e=4(even) f=5(odd) -> 3
        assert split_words("abcdef") == 3

    def test_empty_string(self):
        assert split_words("") == 0

    def test_no_lowercase_letters_uppercase_only(self):
        assert split_words("ABCDEF") == 0

    def test_digits_and_punctuation_only(self):
        assert split_words("123!!!") == 0

    def test_single_odd_letter(self):
        # b -> ord('b')-ord('a') = 1, odd
        assert split_words("b") == 1

    def test_single_even_letter(self):
        # a -> ord('a')-ord('a') = 0, even
        assert split_words("a") == 0

    def test_word_hello(self):
        # h=7(odd) e=4(even) l=11(odd) l=11(odd) o=14(even) -> 3
        assert split_words("hello") == 3

    def test_mixed_case_only_lowercase_counted(self):
        # Only lowercase letters count; uppercase versions ignored regardless of position.
        # b(odd,count) B(ignored) d(odd,count) D(ignored)
        assert split_words("bBdD") == 2

    def test_all_odd_letters(self):
        # b,d,f,h,j,l,n,p,r,t,v,x,z are all odd-positioned
        assert split_words("bdfhjlnprtvxz") == 13

    def test_all_even_letters(self):
        # a,c,e,g,i,k,m,o,q,s,u,w,y are all even-positioned
        assert split_words("acegikmoqsuwy") == 0

    def test_non_alphabetic_characters_ignored_in_count(self):
        assert split_words("b1d2f3!") == 3
