        assert simplify("1/6", "2/1") is False

    def test_example_three_false(self):
        assert simplify("7/10", "10/2") is False


class TestSimplifyWholeNumberResults:
    def test_simple_whole_number(self):
        # (1*2) % (2*1) == 2 % 2 == 0 -> True
        assert simplify("1/2", "2/1") is True

    def test_identity_fraction(self):
        # (1*1) % (1*1) == 0 -> True
        assert simplify("1/1", "1/1") is True

    def test_numerators_multiple_of_denominators(self):
        # x=4/2, n=3/1 -> (4*3) % (2*1) = 12 % 2 = 0 -> True
        assert simplify("4/2", "3/1") is True

    def test_large_numbers_whole_result(self):
        # x=100/10, n=50/5 -> (100*50) % (10*5) = 5000 % 50 = 0 -> True
        assert simplify("100/10", "50/5") is True

    def test_denominator_one_numerator_multiple(self):
        # x=9/3, n=2/1 -> (9*2) % (3*1) = 18 % 3 = 0 -> True
        assert simplify("9/3", "2/1") is True


class TestSimplifyNonWholeResults:
    def test_non_whole_simple(self):
        # x=1/3, n=1/1 -> (1*1) % (3*1) = 1 % 3 = 1 -> False
        assert simplify("1/3", "1/1") is False

    def test_non_whole_larger(self):
        # x=3/4, n=5/7 -> (3*5) % (4*7) = 15 % 28 = 15 -> False
        assert simplify("3/4", "5/7") is False

    def test_close_but_not_whole(self):
        # x=1/2, n=3/2 -> (1*3) % (2*2) = 3 % 4 = 3 -> False
        assert simplify("1/2", "3/2") is False


class TestSimplifyReturnType:
    def test_return_type_is_bool_true_case(self):
        result = simplify("1/5", "5/1")
        assert isinstance(result, bool)
        assert result is True

    def test_return_type_is_bool_false_case(self):
        result = simplify("1/6", "2/1")
        assert isinstance(result, bool)
        assert result is False


class TestSimplifyEdgeCases:
    def test_numerator_zero_in_x(self):
        # x=0/1, n=3/4 -> (0*3) % (1*4) = 0 % 4 = 0 -> True
        assert simplify("0/1", "3/4") is True

    def test_numerator_zero_in_n(self):
        # x=3/4, n=0/1 -> (3*0) % (4*1) = 0 % 4 = 0 -> True
        assert simplify("3/4", "0/1") is True

    def test_both_numerators_zero(self):
        # x=0/5, n=0/7 -> (0*0) % (5*7) = 0 % 35 = 0 -> True
        assert simplify("0/5", "0/7") is True

    def test_multi_digit_numbers(self):
        # x=12/8, n=16/3 -> (12*16) % (8*3) = 192 % 24 = 0 -> True
        assert simplify("12/8", "16/3") is True

    def test_multi_digit_numbers_non_whole(self):
