        ("2/3", "3/2", True),  # (2*3) % (3*2) = 6 % 6 = 0 -> True
        ("5/6", "7/8", False),  # (5*7) % (6*8) = 35 % 48 = 35 -> False
    ],
)
def test_simplify_parametrized(x, n, expected):
