import pytest

from solution import sorted_list_sum


class TestSortedListSum:
    def test_docstring_example_1(self):
        assert sorted_list_sum(["aa", "a", "aaa"]) == ["aa"]

    def test_docstring_example_2(self):
        assert sorted_list_sum(["ab", "a", "aaa", "cd"]) == ["ab", "cd"]

    def test_empty_list(self):
        assert sorted_list_sum([]) == []

    def test_all_odd_length_returns_empty(self):
        assert sorted_list_sum(["a", "abc", "abcde"]) == []

    def test_all_even_length_no_filtering(self):
        assert sorted_list_sum(["dd", "cc", "bb", "aa"]) == ["aa", "bb", "cc", "dd"]

    def test_sorts_by_length_then_alphabetically(self):
        assert sorted_list_sum(
            ["ab", "a", "aaa", "cd", "abcd", "efgh", "zz"]
        ) == ["ab", "cd", "zz", "abcd", "efgh"]

    def test_duplicates_are_preserved(self):
        assert sorted_list_sum(["bb", "aa", "aa", "bb"]) == ["aa", "aa", "bb", "bb"]

    def test_already_sorted_input(self):
        assert sorted_list_sum(["aa", "bb", "abcd"]) == ["aa", "bb", "abcd"]

    def test_reverse_sorted_input(self):
        assert sorted_list_sum(["abcd", "bb", "aa"]) == ["aa", "bb", "abcd"]

    def test_single_even_length_string(self):
        assert sorted_list_sum(["xy"]) == ["xy"]

    def test_single_odd_length_string(self):
        assert sorted_list_sum(["x"]) == []

    def test_empty_string_is_even_length_and_sorts_first(self):
        assert sorted_list_sum(["aa", "", "bb"]) == ["", "aa", "bb"]

    def test_case_sensitive_alphabetical_ordering(self):
        # Uppercase letters sort before lowercase in default Python string
        # comparison, and the implementation relies on plain `<`.
        assert sorted_list_sum(["ba", "AB", "aa"]) == ["AB", "aa", "ba"]

    def test_mixed_lengths_with_ties(self):
        result = sorted_list_sum(
            ["dcba", "abcd", "zz", "aa", "bb", "a", "abc", "abcdef"]
        )
        assert result == ["aa", "bb", "zz", "abcd", "dcba", "abcdef"]

    def test_does_not_mutate_input_list(self):
        original = ["ab", "a", "aaa", "cd"]
        original_copy = list(original)
        sorted_list_sum(original)
        assert original == original_copy

    def test_return_type_is_list(self):
        result = sorted_list_sum(["ab", "cd"])
        assert isinstance(result, list)

    def test_longer_words_of_equal_length(self):
        assert sorted_list_sum(
            ["banana", "apple1", "cherry", "kiwi22"]
        ) == ["apple1", "banana", "cherry", "kiwi22"]

    @pytest.mark.parametrize(
        "lst,expected",
        [
            ([], []),
            (["a"], []),
            (["aa"], ["aa"]),
            (["aaaa", "bb", "aa", "cccc"], ["aa", "bb", "aaaa", "cccc"]),
        ],
    )
    def test_parametrized_cases(self, lst, expected):
        assert sorted_list_sum(lst) == expected
