    def test_returns_y_for_non_primes(self, n):
        assert x_or_y(n, "X", "Y") == "Y"

    @pytest.mark.parametrize(
        "n", [0, 1, 4, 6, 8, 9, 10, 12, 14, 15, 16, 18, 20, 21, 22,
              25, 27, 33, 49, 91, 100]
    )
    def test_known_composites_and_edge_values(self, n):
        assert x_or_y(n, 1, 0) == 0


class TestEdgeCases:
    def test_zero_is_not_prime(self):
        assert x_or_y(0, "prime", "not prime") == "not prime"

