        assert x_or_y(1, "prime", "not prime") == "not prime"

    def test_two_is_prime(self):
        assert x_or_y(2, "prime", "not prime") == "prime"

    def test_three_is_prime(self):
        assert x_or_y(3, "prime", "not prime") == "prime"

    def test_four_is_not_prime(self):
        assert x_or_y(4, "prime", "not prime") == "not prime"

    @pytest.mark.parametrize("n", [-1, -2, -7, -100])
    def test_negative_numbers_are_not_prime(self, n):
        assert x_or_y(n, "prime", "not prime") == "not prime"


class TestReturnValueIdentityAndTypes:
    def test_returns_x_object_unchanged_for_prime(self):
        x_obj = object()
        y_obj = object()
        assert x_or_y(13, x_obj, y_obj) is x_obj

