        assert x_or_y(11, "yes", "no") == "yes"
        assert x_or_y(10, "yes", "no") == "no"

    def test_works_with_none_values(self):
        assert x_or_y(11, None, "no") is None
        assert x_or_y(10, "yes", None) is None

    def test_x_and_y_equal_values(self):
        # When x == y the branch taken shouldn't matter for the result.
        assert x_or_y(11, 42, 42) == 42
        assert x_or_y(10, 42, 42) == 42


