    def test_large_composite(self):
        assert x_or_y(7920, "prime", "not prime") == "not prime"

    def test_perfect_square_of_prime(self):
        # 101 * 101 = 10201, should not be prime
        assert x_or_y(10201, "prime", "not prime") == "not prime"

    def test_square_of_two(self):
        assert x_or_y(9973, "prime", "not prime") == "prime"  # 9973 is prime
