from solution import filter_integers


class TestFilterIntegers:
    def test_docstring_example_mixed_types(self):
        assert filter_integers(['a', 3.14, 5]) == [5]

    def test_docstring_example_multiple_ints(self):
        assert filter_integers([1, 2, 3, 'abc', {}, []]) == [1, 2, 3]

    def test_empty_list(self):
        assert filter_integers([]) == []

    def test_all_integers(self):
        assert filter_integers([1, 2, 3, 4]) == [1, 2, 3, 4]

    def test_no_integers(self):
        assert filter_integers(['a', 'b', 3.14, None, {}, []]) == []

    def test_negative_and_zero_integers(self):
        assert filter_integers([-5, 0, 7]) == [-5, 0, 7]

    def test_strings_excluded(self):
        assert filter_integers(['1', '2', '3']) == []

    def test_floats_excluded(self):
        assert filter_integers([1.0, 2.5, 3.9]) == []

    def test_booleans_excluded(self):
        # type(True) is bool, not int, so booleans should not be included
        assert filter_integers([True, False, 1, 0]) == [1, 0]

    def test_none_excluded(self):
        assert filter_integers([None, 1, None, 2]) == [1, 2]

    def test_lists_and_dicts_excluded(self):
        assert filter_integers([[1, 2], {'a': 1}, (1, 2), 3]) == [3]

    def test_preserves_order(self):
        assert filter_integers([5, 'x', 3, 'y', 1]) == [5, 3, 1]

    def test_duplicates_preserved(self):
        assert filter_integers([1, 1, 2, 2, 'a']) == [1, 1, 2, 2]

    def test_returns_list_type(self):
        result = filter_integers([1, 'a', 2])
        assert isinstance(result, list)

    def test_does_not_mutate_input(self):
        original = [1, 'a', 2, 3.5]
        original_copy = list(original)
        filter_integers(original)
        assert original == original_copy

    def test_mixed_numeric_types(self):
        assert filter_integers([1, 1.0, 2, 2.0, 3]) == [1, 2, 3]

    def test_large_integers(self):
        assert filter_integers([10**10, 'a', 10**20]) == [10**10, 10**20]

    def test_custom_object_excluded(self):
        class Foo:
            pass

        obj = Foo()
        assert filter_integers([obj, 1, 2]) == [1, 2]
