from solution import sum_to_n


class TestSumToN:
    def test_sum_to_30(self):
        assert sum_to_n(30) == 465

    def test_sum_to_100(self):
        assert sum_to_n(100) == 5050

    def test_sum_to_5(self):
        assert sum_to_n(5) == 15

    def test_sum_to_10(self):
        assert sum_to_n(10) == 55

    def test_sum_to_1(self):
        assert sum_to_n(1) == 1

    def test_sum_to_2(self):
        assert sum_to_n(2) == 3

    def test_sum_to_3(self):
        assert sum_to_n(3) == 6

    def test_sum_to_20(self):
        assert sum_to_n(20) == 210

    def test_sum_to_50(self):
        assert sum_to_n(50) == 1275

    def test_sum_to_1000(self):
        assert sum_to_n(1000) == 500500

    def test_return_type_is_int(self):
        assert isinstance(sum_to_n(10), int)

    @pytest.mark.parametrize(
        "n, expected",
        [
            (1, 1),
            (2, 3),
            (3, 6),
            (4, 10),
            (5, 15),
            (6, 21),
            (7, 28),
            (8, 36),
            (9, 45),
            (10, 55),
            (30, 465),
            (100, 5050),
        ],
    )
    def test_parametrized_known_values(self, n, expected):
        assert sum_to_n(n) == expected

    @pytest.mark.parametrize("n", [1, 2, 3, 5, 10, 25, 50, 75, 100, 200])
    def test_matches_reference_gauss_formula(self, n):
        assert sum_to_n(n) == n * (n + 1) // 2

    @pytest.mark.parametrize("n", [1, 2, 3, 5, 10, 25, 50, 75, 100, 200])
    def test_matches_iterative_sum(self, n):
        assert sum_to_n(n) == sum(range(1, n + 1))

