from solution import count_upper


class TestCountUpperDocExamples:
    def test_example_one(self):
        assert count_upper('aBCdEf') == 1

    def test_example_two(self):
        assert count_upper('abcdefg') == 0

    def test_example_three(self):
        assert count_upper('dBBE') == 0


class TestCountUpperBasics:
    def test_empty_string(self):
        assert count_upper('') == 0

    def test_single_uppercase_vowel(self):
        assert count_upper('A') == 1

    def test_single_lowercase_vowel(self):
        assert count_upper('a') == 0

    def test_single_uppercase_consonant(self):
        assert count_upper('B') == 0

    def test_no_vowels_at_all(self):
        assert count_upper('bcdfg') == 0

    def test_all_lowercase_vowels(self):
        assert count_upper('aeiou') == 0


class TestCountUpperEvenIndexPlacement:
    def test_all_even_indices_uppercase_vowels(self):
        # even indices (0,2,4,6,8) are A,E,I,O,U ; odd indices are 'x'
        assert count_upper('AxExIxOxU') == 5

    def test_uppercase_vowels_only_at_odd_indices_not_counted(self):
        # odd indices (1,3,5) are A,E,I ; even indices are 'x'
        assert count_upper('xAxExI') == 0

    def test_uppercase_vowel_at_last_even_index(self):
        # length is odd, last character sits at an even index
        assert count_upper('bcdE') == 0  # E is at index 3 (odd) -> not counted
        assert count_upper('bcdfE') == 1  # E is at index 4 (even) -> counted

    def test_mixed_case_and_positions(self):
        # 'Hello World' -> indices: 0:H 1:e 2:l 3:l 4:o 5:' ' 6:W 7:o 8:r 9:l 10:d
        # even indices: H, l, o, W, r -> none are uppercase vowels
        assert count_upper('Hello World') == 0


class TestCountUpperMixedContent:
    def test_multiple_uppercase_vowels_mixed_with_noise(self):
        # even indices: A, C, E, G, I -> A, E, I are uppercase vowels
        assert count_upper('AbCdEfGhI') == 3

    def test_uppercase_consonants_at_even_indices_not_counted(self):
        # even indices: B, D, F -> none are vowels
        assert count_upper('BaDaFa') == 0

    def test_digits_and_symbols_at_even_indices(self):
        # even indices: '1', '-', 'A' -> only 'A' is an uppercase vowel
        assert count_upper('1a-aAa') == 1

    def test_repeated_string_from_docstring_style(self):
        assert count_upper('ABCDEF') == 2  # even indices: A, C, E -> A and E are vowels
