import pytest

from solution import split_words


class TestSplitWordsWhitespace:
    """When the input contains any whitespace character, split on whitespace."""

    def test_simple_space_separated_words(self):
        assert split_words("Hello world!") == ["Hello", "world!"]

    def test_multiple_words_separated_by_single_spaces(self):
        assert split_words("The quick brown fox") == ["The", "quick", "brown", "fox"]

    def test_collapses_multiple_spaces(self):
        assert split_words("Hello   world") == ["Hello", "world"]

    def test_strips_leading_and_trailing_spaces(self):
        assert split_words("  Hello world  ") == ["Hello", "world"]

    def test_splits_on_tab(self):
        assert split_words("Hello\tworld") == ["Hello", "world"]

    def test_splits_on_newline(self):
        assert split_words("Hello\nworld") == ["Hello", "world"]

    def test_whitespace_takes_priority_over_comma(self):
        assert split_words("Hello, world") == ["Hello,", "world"]

    def test_commas_preserved_as_part_of_word_when_whitespace_present(self):
        assert split_words("Hello,world! foo") == ["Hello,world!", "foo"]

    def test_single_word_with_surrounding_whitespace(self):
