Unit tests for `compare_one`.

The function returns the larger of two values that may be given as
int, float, or string (with '.' or ',' as decimal separator),
preserving the original type/value of whichever input was larger.
It returns None when the two values represent an equal real number.
"""

import pytest

from solution import compare_one


class TestNumericTypes:
    """Both arguments are plain int/float."""

    def test_int_vs_int_first_larger(self):
        assert compare_one(5, 2) == 5

    def test_int_vs_int_second_larger(self):
        assert compare_one(2, 5) == 5

    def test_float_vs_float_first_larger(self):
        assert compare_one(3.7, 1.2) == 3.7

    def test_float_vs_float_second_larger(self):
        assert compare_one(1.2, 3.7) == 3.7

    def test_int_vs_float_second_larger(self):
        assert compare_one(1, 2.5) == 2.5

    def test_int_vs_float_first_larger(self):
        assert compare_one(4, 2.5) == 4

    def test_equal_ints_returns_none(self):
        assert compare_one(1, 1) is None

    def test_equal_floats_returns_none(self):
        assert compare_one(2.5, 2.5) is None

    def test_equal_int_and_float_returns_none(self):
        assert compare_one(2, 2.0) is None

