import pytest

from solution import sorted_list_sum


def test_example_one():
    assert sorted_list_sum(["aa", "a", "aaa"]) == ["aa"]


def test_example_two():
    assert sorted_list_sum(["ab", "a", "aaa", "cd"]) == ["ab", "cd"]


def test_removes_all_odd_length_strings():
    result = sorted_list_sum(["a", "abc", "abcde"])
    assert result == []


def test_keeps_all_even_length_strings():
    result = sorted_list_sum(["ab", "cd", "efgh"])
    assert result == ["ab", "cd", "efgh"]


def test_empty_list_returns_empty_list():
    assert sorted_list_sum([]) == []


def test_sorted_by_length_ascending():
    result = sorted_list_sum(["abcd", "ab", "abcdef", "cd"])
    assert result == ["ab", "cd", "abcd", "abcdef"]


def test_same_length_sorted_alphabetically():
    result = sorted_list_sum(["dc", "ba", "ab", "cd"])
    assert result == ["ab", "ba", "cd", "dc"]


def test_mixed_lengths_and_alphabetical_tiebreak():
    result = sorted_list_sum(["bbbb", "aaaa", "cd", "ab", "abcdef"])
    assert result == ["ab", "cd", "aaaa", "bbbb", "abcdef"]


def test_handles_duplicates():
    result = sorted_list_sum(["ab", "ab", "cd", "a"])
    assert result == ["ab", "ab", "cd"]


def test_does_not_mutate_input_list():
    original = ["dcba", "ab", "a", "cd"]
    original_copy = list(original)
    sorted_list_sum(original)
    assert original == original_copy


def test_single_even_length_string():
    assert sorted_list_sum(["hello world"[:10]]) == ["hello worl"]


def test_all_same_word_repeated():
    result = sorted_list_sum(["xy", "xy", "xy"])
    assert result == ["xy", "xy", "xy"]


def test_longer_list_with_various_lengths():
    words = ["ccccc", "bb", "dddd", "aa", "ffffff", "ee"]
    result = sorted_list_sum(words)
    assert result == ["aa", "bb", "ee", "dddd", "ffffff"]


def test_uppercase_and_lowercase_alphabetical_order():
    # Uppercase letters sort before lowercase in standard string comparison
    result = sorted_list_sum(["ba", "Ab", "AB", "ab"])
    assert result == sorted(["ba", "Ab", "AB", "ab"], key=lambda s: (len(s), s))


def test_return_type_is_list():
    result = sorted_list_sum(["ab", "cd"])
    assert isinstance(result, list)
