import pytest

from solution import words_string

EXPECTED_BASIC_RESULT = ["Hi", "my", "name", "is", "John"]
EXPECTED_COMMA_RESULT = ["One", "two", "three", "four", "five", "six"]


class TestWordsStringBasic:
    """Tests for typical, well-formed inputs."""

    def test_mixed_commas_and_spaces(self):
        assert words_string("Hi, my name is John") == EXPECTED_BASIC_RESULT

    def test_comma_separated_with_spaces(self):
        result = words_string("One, two, three, four, five, six")
        assert result == EXPECTED_COMMA_RESULT

    def test_space_only_separator(self):
        assert words_string("apple banana cherry") == ["apple", "banana", "cherry"]

    def test_comma_only_separator_no_spaces(self):
        assert words_string("apple,banana,cherry") == ["apple", "banana", "cherry"]

    def test_single_word(self):
        assert words_string("hello") == ["hello"]


class TestWordsStringEdgeCases:
    """Tests for empty, whitespace-heavy, and irregularly formatted inputs."""

    def test_empty_string_returns_empty_list(self):
        assert words_string("") == []

    def test_only_spaces_returns_empty_list(self):
        assert words_string("     ") == []

    def test_only_commas_returns_empty_list(self):
        assert words_string(",,,,") == []

    def test_only_commas_and_spaces_returns_empty_list(self):
        assert words_string(" , , , ") == []

    def test_multiple_consecutive_commas(self):
        assert words_string("apple,,banana,,,cherry") == ["apple", "banana", "cherry"]

    def test_multiple_consecutive_spaces(self):
        assert words_string("apple    banana     cherry") == ["apple", "banana", "cherry"]

    def test_leading_and_trailing_separators(self):
        assert words_string(" , apple, banana ,") == ["apple", "banana"]

    def test_leading_and_trailing_whitespace(self):
        assert words_string("  apple banana  ") == ["apple", "banana"]

    def test_mixed_consecutive_commas_and_spaces(self):
        result = words_string("apple, , banana,  , cherry")
        assert result == ["apple", "banana", "cherry"]


class TestWordsStringContent:
    """Tests that verify content, ordering, and value preservation."""

    def test_preserves_word_order(self):
        result = words_string("zebra, apple, mango")
        assert result == ["zebra", "apple", "mango"]

    def test_preserves_case(self):
        result = words_string("Hello, WORLD, MixedCase")
        assert result == ["Hello", "WORLD", "MixedCase"]

    def test_words_with_numbers(self):
        assert words_string("item1, item2, item3") == ["item1", "item2", "item3"]

    def test_single_character_words(self):
        assert words_string("a, b, c") == ["a", "b", "c"]

    def test_return_type_is_list(self):
        result = words_string("Hi, my name is John")
        assert isinstance(result, list)

    def test_all_elements_are_strings(self):
        result = words_string("Hi, my name is John")
        assert all(isinstance(word, str) for word in result)


@pytest.mark.parametrize(
