"""Unit tests for the by_length function from the solution module."""

import pytest

from solution import by_length


def test_example_from_docstring() -> None:
    arr = [2, 1, 1, 4, 5, 8, 2, 3]
    expected = ["Eight", "Five", "Four", "Three", "Two", "Two", "One", "One"]
    assert by_length(arr) == expected


def test_empty_array_returns_empty_list() -> None:
    assert by_length([]) == []


def test_ignores_out_of_range_numbers() -> None:
    assert by_length([1, -1, 55]) == ["One"]


def test_ignores_zero() -> None:
    assert by_length([0, 3, 9]) == ["Nine", "Three"]


def test_ignores_negative_numbers() -> None:
    assert by_length([-5, -3, -1]) == []


def test_ignores_numbers_greater_than_nine() -> None:
    assert by_length([10, 20, 100]) == []


def test_all_digits_one_through_nine_in_order() -> None:
    arr = [1, 2, 3, 4, 5, 6, 7, 8, 9]
    expected = ["Nine", "Eight", "Seven", "Six", "Five", "Four", "Three", "Two", "One"]
    assert by_length(arr) == expected


def test_single_valid_element() -> None:
    assert by_length([5]) == ["Five"]


def test_single_invalid_element() -> None:
    assert by_length([42]) == []


def test_duplicates_are_preserved() -> None:
    assert by_length([3, 3, 3]) == ["Three", "Three", "Three"]


def test_unsorted_input_is_sorted_then_reversed() -> None:
    assert by_length([9, 1, 5, 3]) == ["Nine", "Five", "Three", "One"]


def test_mixed_valid_and_invalid_values() -> None:
    arr = [-10, 0, 2, 15, 7, 9, 200]
    expected = ["Nine", "Seven", "Two"]
    assert by_length(arr) == expected


def test_result_is_a_list() -> None:
    result = by_length([1, 2, 3])
    assert isinstance(result, list)


@pytest.mark.parametrize(
    "digit, word",
    [
        (1, "One"),
        (2, "Two"),
        (3, "Three"),
        (4, "Four"),
        (5, "Five"),
        (6, "Six"),
        (7, "Seven"),
        (8, "Eight"),
        (9, "Nine"),
    ],
)
def test_each_digit_maps_to_expected_word(digit: int, word: str) -> None:
    assert by_length([digit]) == [word]


def test_does_not_mutate_input_array() -> None:
    arr = [3, 1, 2]
    original_copy = arr[:]
    by_length(arr)
    assert arr == original_copy
