import pytest

from solution import get_odd_collatz

BASE_CASE_INPUT = 1
BASE_CASE_EXPECTED = [1]


class TestGetOddCollatz:
    """Test suite covering base cases, typical inputs, and ordering guarantees."""

    def test_base_case_returns_single_element(self) -> None:
        assert get_odd_collatz(BASE_CASE_INPUT) == BASE_CASE_EXPECTED

    def test_example_five(self) -> None:
        assert get_odd_collatz(5) == [1, 5]

    def test_even_start_value(self) -> None:
        # Collatz(4) -> [4, 2, 1], odd numbers are only 1.
        assert get_odd_collatz(4) == [1]

    def test_power_of_two(self) -> None:
        # Collatz(8) -> [8, 4, 2, 1], odd numbers are only 1.
        assert get_odd_collatz(8) == [1]

    def test_larger_sequence(self) -> None:
        # Collatz(6) -> [6, 3, 10, 5, 16, 8, 4, 2, 1], odds are 3, 5, 1.
        assert get_odd_collatz(6) == [1, 3, 5]

    def test_known_long_sequence(self) -> None:
        # Collatz(7) -> 7, 22, 11, 34, 17, 52, 26, 13, 40, 20, 10, 5, 16, 8, 4, 2, 1
        expected = sorted({7, 11, 17, 13, 5, 1})
        assert get_odd_collatz(7) == expected

    @pytest.mark.parametrize("n", [1, 2, 3, 5, 6, 7, 9, 10, 27, 97])
    def test_result_is_sorted(self, n: int) -> None:
        result = get_odd_collatz(n)
        assert result == sorted(result)

    @pytest.mark.parametrize("n", [1, 2, 3, 5, 6, 7, 9, 10, 27, 97])
    def test_result_contains_only_odd_numbers(self, n: int) -> None:
        result = get_odd_collatz(n)
        assert all(value % 2 == 1 for value in result)

    @pytest.mark.parametrize("n", [1, 2, 3, 5, 6, 7, 9, 10, 27, 97])
    def test_result_always_contains_one(self, n: int) -> None:
        assert 1 in get_odd_collatz(n)

    @pytest.mark.parametrize("n", [1, 2, 3, 5, 6, 7, 9, 10, 27, 97])
    def test_odd_start_value_included_in_result(self, n: int) -> None:
        if n % 2 == 1:
            assert n in get_odd_collatz(n)

    def test_no_duplicate_values_for_typical_input(self) -> None:
        result = get_odd_collatz(27)
        assert len(result) == len(set(result))

    def test_return_type_is_list(self) -> None:
        assert isinstance(get_odd_collatz(10), list)
