import pytest

from solution import eat

MAX_CARROTS = 1000


class TestEatProvidedExamples:
    """Tests based on the examples given in the eat function's docstring."""

    def test_example_one(self) -> None:
        assert eat(5, 6, 10) == [11, 4]

    def test_example_two(self) -> None:
        assert eat(4, 8, 9) == [12, 1]

    def test_example_three(self) -> None:
        assert eat(1, 10, 10) == [11, 0]

    def test_example_four(self) -> None:
        assert eat(2, 11, 5) == [7, 0]


class TestEatEnoughRemaining:
    """Tests for the case where remaining carrots satisfy the need."""

    def test_need_less_than_remaining(self) -> None:
        assert eat(0, 3, 10) == [3, 7]

    def test_need_equal_to_remaining(self) -> None:
        assert eat(0, 10, 10) == [10, 0]

    def test_need_zero(self) -> None:
        assert eat(3, 0, 5) == [3, 5]

    def test_number_already_eaten_carried_over(self) -> None:
        assert eat(20, 5, 5) == [25, 0]


class TestEatInsufficientRemaining:
    """Tests for the case where remaining carrots cannot satisfy the need."""

    def test_need_greater_than_remaining(self) -> None:
        assert eat(0, 10, 3) == [3, 0]

    def test_remaining_is_zero(self) -> None:
        assert eat(5, 5, 0) == [5, 0]

    def test_number_and_remaining_both_nonzero(self) -> None:
        assert eat(7, 20, 4) == [11, 0]


class TestEatBoundaryValues:
    """Tests for boundary values as defined by the function's constraints."""

    def test_all_zero(self) -> None:
        assert eat(0, 0, 0) == [0, 0]

    def test_maximum_values_need_equals_remaining(self) -> None:
        assert eat(MAX_CARROTS, MAX_CARROTS, MAX_CARROTS) == [
            MAX_CARROTS + MAX_CARROTS,
            0,
        ]

    def test_maximum_need_zero_remaining(self) -> None:
        assert eat(0, MAX_CARROTS, 0) == [0, 0]

    def test_maximum_remaining_zero_need(self) -> None:
        assert eat(0, 0, MAX_CARROTS) == [0, MAX_CARROTS]


class TestEatReturnType:
    """Tests that validate the structure and type of the returned value."""

    @pytest.mark.parametrize(
        ("number", "need", "remaining"),
        [
            (5, 6, 10),
            (4, 8, 9),
            (1, 10, 10),
            (2, 11, 5),
